-- ET-L2 Module 2 — Multi-frequency Techniques (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Mengapa multi-frequency — batas single frequency', '{"slides":[{"heading":"Masalah inti: sinyal pengganggu","body":"Pada inspeksi tube single-frequency, sinyal defect bercampur dengan lift-off (variasi probe-to-surface gap akibat fill factor tidak sempurna), support plate (tube support / baffle plate), dan dent/geometry. Indikasi pit kecil OD bisa tenggelam dalam respon support plate yang amplitudonya 5-10x lebih besar. Operator tidak bisa membedakan mana defect mana artefak — inilah motivasi utama multi-frequency."},{"heading":"Prinsip pemisahan: phase angle","body":"Pada impedance plane, setiap sumber sinyal punya phase angle khas. Lift-off cenderung horizontal (setelah probe di-null), sedangkan flaw OD memutar phase. Support plate menghasilkan loop besar dengan phase yang dapat diprediksi. Karena tiap fenomena fisik merespon perubahan frekuensi secara berbeda, kita pakai >1 frekuensi untuk ''memisahkan'' lalu mengurangkan sinyal pengganggu."},{"heading":"Skin depth menentukan pilihan frekuensi","body":"Standard depth of penetration (skin depth) delta = 1/sqrt(pi*f*mu*sigma), yaitu kedalaman di mana densitas eddy current turun ke 37% (1/e). Bentuk praktis: delta[mm] ~ 21/sqrt(f[kHz]*sigma[%IACS]*mu_r). Contoh anchor: aluminium 100 kHz, sigma~40 %IACS, mu_r=1 -> delta ~ 0.33 mm. Frekuensi tinggi = delta kecil = sensitif defect dangkal/ID; frekuensi rendah = delta besar = penetrasi ke OD/wall. Multi-frequency mengeksploitasi perbedaan respon delta ini."},{"heading":"Phase lag = informasi kedalaman","body":"Phase lag beta ~ x/delta radian: makin dalam flaw, makin besar rotasi phase relatif sinyal permukaan. Inilah alasan flaw OD dan ID terpisah secara phase pada layar. Dengan dua frekuensi yang delta-nya berbeda, kita mendapat dua ''view'' dengan rotasi phase berbeda untuk sinyal yang sama, sehingga mixing dapat menghapus salah satunya tanpa menghilangkan yang lain."}]}', 460, NULL),
  (2, 'reading', 'Two-frequency mixing — mekanisme', '{"slides":[{"heading":"Channel A dan Channel B","body":"Channel A = frekuensi prime (defect-sensitive), dipilih agar respon flaw maksimum. Channel B = frekuensi referensi, dipilih agar respon sinyal pengganggu (lift-off atau support plate) menonjol sementara respon flaw minim. Contoh tube Inconel/Ni-alloy: prime f1 ~ 35 kHz untuk wall defect, referensi f2 ~ 10 kHz menonjolkan support plate (nilai ilustratif, sesuaikan dengan reference tube)."},{"heading":"Operasi mix = A - k*B(theta)","body":"Mixing bukan sekadar pengurangan mentah. Sinyal channel B di-scale (gain k) dan di-rotate (phase theta) sampai respon support plate pada B menyamai bentuk & amplitudo pada A, lalu dikurangkan: Mix = A - k*B(theta). Hasilnya sinyal support plate hampir nol (cancelled), sedangkan respon flaw — yang berbeda rasionya di kedua frekuensi — tetap tersisa."},{"heading":"Mengapa flaw tidak ikut hilang","body":"Support plate adalah perubahan eksternal yang merespon kedua frekuensi dengan rasio amplitudo/phase yang dapat dicocokkan persis sehingga ter-cancel. Flaw (terutama OD pit di bawah support plate) merespon f1 dan f2 dengan rasio berbeda karena skin depth berbeda, sehingga tidak ter-null oleh mix yang dioptimasi untuk support plate. Itulah kunci ''defect under support plate detection''."},{"heading":"Lift-off cancellation","body":"Untuk inspeksi permukaan (surface/pencil probe), salah satu kanal direferensikan ke lift-off. Karena lift-off pada impedance plane horizontal dan stabil setelah probe di-null, mixing/rotasi membuatnya nol sementara flaw yang vertikal tetap muncul. Pada bobbin tube, ''lift-off'' ekuivalen dengan variasi fill factor dan dent — juga ditekan via kanal referensi frekuensi rendah."}]}', 500, NULL),
  (3, 'reading', 'Setup, kalibrasi, dan tuning mix', '{"slides":[{"heading":"Reference standard untuk mixing","body":"Pakai calibration tube dengan support plate ring simulasi (atau collar) plus flaw buatan: through-wall hole, flat-bottom hole bertingkat (mis. 20% / 40% / 60% / 80% OD), dan groove. ASME V Article 8 mengatur reference standard tube ET; ASTM E309 (eddy current bobbin tube dengan magnetic saturation untuk tube) dan ASTM E243 (Cu-alloy tube) adalah practice yang relevan. Support plate ring harus material & dimensi mewakili kondisi lapangan."},{"heading":"Prosedur tuning dua frekuensi","body":"1) Null probe di area bersih. 2) Tarik probe melewati support plate tanpa flaw. 3) Amati respon support plate di channel A & B. 4) Adjust gain (k) dan phase (theta) pada channel B sampai loop support plate di A dan B kongruen. 5) Aktifkan mix; verifikasi residual support plate di bawah kriteria (mis. < 20% FSH). 6) Tarik probe melewati flaw under support plate — flaw harus tetap terdeteksi dan terklasifikasi."},{"heading":"Pemilihan rasio frekuensi","body":"Aturan praktis: f-prime dipilih agar phase separation flaw OD vs ID memadai (sering pada f di mana wall ~ 1-1.5 delta). f-reference biasanya 1/3 sampai 1/4 dari f-prime untuk menonjolkan struktur eksternal / penetrasi dalam. Frekuensi terlalu dekat -> mix tidak efektif (sinyal hampir identik, tidak ada diskriminasi); terlalu jauh -> SNR flaw turun. Dokumentasikan dalam written procedure (kompetensi Level II)."},{"heading":"Validasi & dokumentasi","body":"Setelah mix di-set, rekam: f1, f2, gain tiap channel, phase tiap channel, mix coefficient, fill factor, drive voltage, scan speed. Buktikan deteksi flaw under support plate pada reference standard sebelum produksi. Level II bertanggung jawab sign-off setup dan menulis prosedur; kualifikasi peralatan/operator mengacu ISO 15548/15549 dan ASME V Article 8."}]}', 500, NULL),
  (4, 'reading', 'Three-frequency & aplikasi lapangan', '{"slides":[{"heading":"Kapan butuh tiga frekuensi","body":"Heat exchanger dengan banyak tipe diskontinuitas geometris (multiple support plate, tubesheet, dent) membutuhkan lebih dari satu mix. Three-frequency = dua operasi mixing: mix-1 menekan support plate, mix-2 menekan dent/tubesheet. Tiap mix menggunakan pasangan kanal yang dioptimasi untuk artefak spesifiknya."},{"heading":"Strategi kanal multi-mix","body":"Contoh konfigurasi ilustratif untuk thin-wall Ni-alloy tube: f1=35 kHz (prime), f2=10 kHz (support plate ref, penetrasi dalam), f3=100 kHz (near-surface/ID ref, delta kecil). Mix-A = f1 vs f2 (hapus support plate). Mix-B = f1 vs f3 (hapus ID lift-off/fill factor). Operator memantau channel raw + channel mix bersamaan untuk konfirmasi silang indikasi."},{"heading":"Batas dan jebakan","body":"Mixing tidak menciptakan informasi — ia menukar SNR. Over-mixing dapat menghapus flaw real yang phase-nya mirip artefak. Flaw tepat di bawah support plate selalu lebih sulit (degradasi sensitivitas tetap ada). Untuk tube ferromagnetik, mixing bobbin tidak cukup — beralih ke RFT (through-transmission, phase=depth, sensitivitas OD/ID setara, ~full wall) atau IRIS (ultrasonic, wall thickness akurat)."},{"heading":"Tanggung jawab Level II","body":"Level II memilih teknik (single vs 2F vs 3F vs RFT/IRIS), menetapkan frekuensi & mix, mengkalibrasi pada reference standard, menafsir indikasi mix, dan sign-off hasil. Keputusan ini didokumentasikan dalam written procedure dengan technique demonstration sesuai ASME V Article 8."}]}', 460, NULL),
  (5, 'quiz', 'Mini-quiz — Multi-frequency Techniques', '{"description":"7 soal: mixing channel, lift-off cancellation, support plate suppression, dan pemilihan teknik Level II.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 2
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- ET-L2 Module 2 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'ET-L2' AND m."orderIndex" = 2 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'ET', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada two-frequency mixing untuk inspeksi tube, apa fungsi utama channel B (frekuensi referensi)?',
   '["Menonjolkan sinyal pengganggu (mis. support plate / lift-off) agar dapat dicocokkan dan dikurangkan dari channel A","Memaksimalkan amplitudo sinyal flaw agar mudah terlihat","Mengukur ketebalan dinding secara absolut","Menggantikan kebutuhan reference standard saat kalibrasi"]', 0,
   'Channel B (referensi) dipilih agar sinyal pengganggu menonjol; setelah di-scale dan di-rotate hingga kongruen dengan channel A, ia dikurangkan sehingga artefak ter-cancel sementara flaw tetap tersisa.', 'Multi-frequency Mixing', 'easy'),
  ('Operasi mixing yang benar untuk menghapus support plate dapat dirumuskan sebagai:',
   '["Mix = A + B tanpa penyesuaian apa pun","Mix = A x B (perkalian langsung kedua sinyal)","Mix = A - k*B(theta), dengan channel B di-scale (gain k) dan di-rotate (phase theta) agar respon support plate-nya kongruen dengan A","Mix = rata-rata aritmetika A dan B"]', 2,
   'Mixing bukan pengurangan mentah: channel B harus di-scale dan di-rotate dulu hingga bentuk & amplitudo support plate cocok dengan channel A, baru dikurangkan sehingga support plate ter-null.', 'Multi-frequency Mixing', 'medium'),
  ('Mengapa flaw (mis. OD pit di bawah support plate) tetap terdeteksi setelah mix yang dioptimasi untuk menghapus support plate?',
   '["Karena flaw selalu lebih besar amplitudonya daripada support plate","Karena flaw dan support plate merespon kedua frekuensi dengan rasio amplitudo/phase berbeda (akibat skin depth berbeda), sehingga flaw tidak ter-null oleh mix","Karena flaw hanya muncul di channel B, bukan channel A","Karena mixing menambah gain pada sinyal flaw secara otomatis"]', 1,
   'Support plate dapat dicocokkan persis di kedua frekuensi sehingga ter-cancel. Flaw merespon f1 dan f2 dengan rasio berbeda karena perbedaan skin depth, jadi tidak ter-null oleh mix yang disetel untuk support plate.', 'Multi-frequency Mixing', 'hard'),
  ('Dengan bentuk praktis delta[mm] ~ 21/sqrt(f[kHz]*sigma[%IACS]*mu_r), pada aluminium 100 kHz, sigma~40 %IACS, mu_r=1, skin depth (standard depth of penetration) mendekati:',
   '["3.3 mm","1.0 mm","0.033 mm","0.33 mm"]', 3,
   '21/sqrt(100*40*1) = 21/sqrt(4000) = 21/63.2 ~ 0.33 mm. Ini nilai anchor: frekuensi tinggi memberi skin depth kecil (sensitif near-surface/ID).', 'Skin Depth', 'medium'),
  ('Dalam lift-off cancellation pada surface/pencil probe, mengapa lift-off relatif mudah ditekan dibanding flaw?',
   '["Karena lift-off tidak menghasilkan sinyal sama sekali","Karena lift-off muncul horizontal dan stabil pada impedance plane setelah probe di-null, sehingga rotasi/mix dapat membuatnya nol sementara flaw yang vertikal tetap muncul","Karena lift-off selalu berada pada frekuensi yang berbeda dari flaw","Karena flaw dan lift-off memiliki phase angle yang identik"]', 1,
   'Instrumen merotasi phase agar lift-off horizontal (dan flaw vertikal). Karena arah lift-off konsisten dan terpisah secara phase dari flaw, mixing/rotasi dapat menekannya tanpa menghilangkan komponen flaw yang tegak lurus.', 'Lift-off Cancellation', 'medium'),
  ('Saat tuning mix pada reference standard, kriteria keberhasilan penekanan support plate yang tepat adalah:',
   '["Sinyal flaw pada channel A harus menjadi nol","Channel B menampilkan loop support plate sebesar mungkin","Residual support plate pada channel mix turun di bawah ambang (mis. < 20% FSH) sementara flaw under support plate tetap terdeteksi","Gain channel A dan B harus selalu sama persis"]', 2,
   'Setelah gain & phase channel B disetel kongruen, mix harus menyisakan residual support plate minimal (mis. < 20% FSH) DAN tetap mendeteksi flaw under support plate pada reference standard sebelum produksi.', 'Kalibrasi & Setup', 'medium'),
  ('Sebuah tube heat exchanger berbahan ferromagnetik (mis. carbon steel) gagal diinspeksi memadai dengan bobbin ET meskipun sudah memakai two-frequency mixing. Tindakan Level II yang paling tepat adalah:',
   '["Menambah frekuensi keempat dan kelima pada bobbin untuk memperkuat mixing","Beralih ke metode yang sesuai untuk material ferromagnetik, mis. RFT (through-transmission, phase=depth, sensitivitas OD/ID setara) atau IRIS (ultrasonic)","Menaikkan drive voltage hingga maksimum agar sinyal menembus dinding","Menggunakan IRIS karena IRIS adalah metode eddy current khusus tube ferromagnetik"]', 1,
   'Permeabilitas tinggi material ferromagnetik membuat skin depth sangat kecil sehingga bobbin ET (berapa pun jumlah frekuensinya) tidak menembus dinding. Solusinya beralih metode: RFT untuk tube ferromagnetik (phase=depth, sensitivitas OD/ID setara, ~full wall) atau IRIS yang berbasis ultrasonik (bukan eddy current).', 'Pemilihan Teknik', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 2 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- ET-L2 Module 3 — Array Probe Mastery (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Anatomi array probe — dari single coil ke matrix', '{"slides":[{"heading":"Mengapa array","body":"Single-element pencil probe hanya melihat satu titik per scan line — coverage area besar butuh raster mekanik yang lambat dan rawan miss. Array probe menyusun banyak coil kecil dalam satu housing. Satu pass = lebar coverage tipikal 25-50 mm sekaligus, lengkap dengan C-scan imaging. Untuk inspeksi weld, fastener row, dan blade root, array memangkas waktu scan 5-10x dibanding pencil probe, sambil memberi rekaman permanen yang dapat diaudit."},{"heading":"Multiplexing","body":"Kunci array adalah multiplexing: instrument tidak menyalakan semua coil serentak (akan saling induksi / cross-talk dan merusak sinyal), tapi mengaktifkan coil secara sequential dalam time-slot mikrodetik. Electronic multiplexer men-switch eksitasi dan akuisisi antar elemen. Tiap coil punya address; firmware merekonstruksi posisi spasial menjadi gambar. Prinsip akuisisi multi-coil ini dibakukan di ASTM E2884."},{"heading":"Topologi coil","body":"Tiga mode dasar: (1) Absolute array — tiap coil membaca nilai mutlak, bagus untuk gradual wall loss dan dimensi/sizing. (2) Differential array — pasangan coil berdekatan, peka crack tajam, menolak lift-off dan thermal drift. (3) Transmit-receive / driver-pickup (TR) — coil pemancar terpisah dari penerima, fleksibel mengarahkan sensitivitas dan toleran geometry. Banyak array komersial menggabungkan beberapa mode dalam satu probe."},{"heading":"Encoder & resolusi","body":"Array dipasangkan dengan position encoder agar tiap A-scan ter-tag koordinat untuk membentuk C-scan. Resolusi gambar dibatasi pitch (jarak antar coil, tipikal 1-5 mm) pada sumbu lateral, dan oleh encoder step pada sumbu scan. Cacat lebih kecil dari pitch bisa lolos di antara coil — inilah dasar penentuan strategi index/overlap dan staggering coil."}]}', 460, NULL),
  (2, 'reading', 'Konfigurasi & seleksi frekuensi array', '{"slides":[{"heading":"Memilih frekuensi","body":"Aturan skin depth tetap berlaku per coil: delta[mm] ~ 21/sqrt(f[kHz]*sigma[%IACS]*mu_r). Contoh aluminium (sigma ~40 %IACS, mu_r=1) pada 100 kHz -> delta ~ 0.33 mm. Skin depth turun bila frekuensi, konduktivitas, atau permeabilitas naik. Untuk surface crack pilih frekuensi tinggi (sensitif, penetrasi dangkal); untuk subsurface yang lebih dalam turunkan frekuensi agar penetrasi cukup. Array modern bersifat multi-frequency: tiap elemen bisa di-drive di beberapa frekuensi bergantian."},{"heading":"Pitch, gap, dan dead zone","body":"Pitch menentukan resolusi lateral; gap antar coil menciptakan zona sensitivitas rendah. Solusi: row coil di-stagger (dua baris zig-zag) sehingga coil baris kedua menutupi gap baris pertama — efektif menggandakan resolusi lateral tanpa memperkecil pitch fisik. Saat menyusun procedure, dokumentasikan effective coverage width dan posisi dead zone di tepi probe."},{"heading":"Mode operasi vs target cacat","body":"Cocokkan topologi dengan defect: differential (crack axial/transverse tajam pada weld dan fastener), absolute (corrosion mapping, thinning, dimensi pit), TR (cacat subsurface, material tebal, lebih toleran geometry). Banyak inspeksi weld dijalankan dual-mode: differential untuk deteksi crack + absolute untuk konfirmasi dan sizing dalam satu pass."},{"heading":"Fleksibel vs rigid array","body":"Flexible/conformable array mengikuti kontur (nozzle radius, blade root, fillet weld) menjaga lift-off konstan — kritis karena lift-off variabel merusak fasa dan amplitudo. Rigid array dipakai untuk permukaan datar/silindris dengan jig. Saat probe melengkung, pitch efektif berubah; karena itu kalibrasi harus dilakukan pada mock-up dengan radius yang sama dengan komponen."}]}', 500, NULL),
  (3, 'reading', 'Kalibrasi & standardisasi C-scan', '{"slides":[{"heading":"Reference standard array","body":"Pakai reference block dengan material dan kondisi sama dengan part, berisi EDM notch / flat-bottom hole pada kedalaman bertingkat (mis. 20%, 40%, 60% wall). Block harus cukup lebar agar SELURUH elemen array melewati setiap reflektor — wajib untuk channel balancing. Per ASTM E2884, semua coil harus diverifikasi merespons reflektor acuan secara seragam sebelum scan produksi."},{"heading":"Channel balancing & normalisasi","body":"Tantangan unik array: tiap coil sedikit berbeda akibat toleransi manufaktur dan panjang jalur multiplexer. Lewatkan array di atas notch acuan, lalu instrument menormalkan gain tiap channel agar respons amplitudo seragam — channel/gain balancing. Tanpa ini, C-scan menampilkan garis terang/gelap palsu (banding) yang menyamar sebagai indikasi. Tandai dan buang dead channel sebelum scan produksi."},{"heading":"Rotasi fasa & null lift-off","body":"Sama seperti single coil: putar fasa sehingga sinyal lift-off horizontal dan sinyal flaw vertikal di impedance plane, diterapkan per channel atau global. Phase lag beta ~ x/delta radian — cacat lebih dalam berputar lebih jauh, dasar untuk depth sizing. Set null/balance saat probe berada di area bebas cacat dengan lift-off representatif."},{"heading":"Sensitivitas, threshold, & validasi","body":"Set gain agar notch acuan terkecil mencapai amplitudo evaluasi (mis. 80% FSH) dengan SNR memadai (umumnya >=3:1, atau sesuai code). Tetapkan color palette/threshold C-scan terhadap reflektor acuan. Lakukan kalibrasi awal, verifikasi ulang tiap interval waktu / jumlah part, dan saat probe atau setup berubah. Catat semua di calibration log untuk audit dan Level II sign-off."}]}', 510, NULL),
  (4, 'reading', 'Strategi scan, C-scan, & interpretasi', '{"slides":[{"heading":"Orientasi & overlap","body":"Orientasikan sumbu sensitif array tegak lurus terhadap orientasi cacat yang diharapkan (mis. differential coils melintang terhadap crack axial). Untuk area lebih lebar dari probe, gunakan index pass dengan overlap >=10-20% agar dead zone tepi tertutup. Jaga kecepatan scan agar sampling encoder cukup rapat — terlalu cepat menyebabkan aliasing dan cacat kecil terlewat."},{"heading":"Membaca C-scan","body":"C-scan adalah peta top-view: posisi X-Y dari encoder + lateral coil, warna = amplitudo (atau fasa). Crack tampak sebagai garis/streak terarah; corrosion pit sebagai blob terlokalisasi; banding seragam lintas seluruh lebar sejajar arah scan biasanya artefak channel imbalance, bukan cacat. Selalu kembali ke A-scan/impedance plane channel terkait untuk evaluasi sinyal sebenarnya sebelum dispositioning."},{"heading":"Membedakan cacat vs geometry","body":"Edge effect, fastener, support plate, dan perubahan ketebalan menimbulkan sinyal kuat. Manfaatkan fasa: cacat punya phase angle khas yang berbeda dari lift-off/geometry; gunakan juga mixing multi-frekuensi untuk menekan sinyal geometry (channel A defect-sensitive + channel B reference -> mix A-B membatalkan sinyal geometry). Korelasikan indikasi dengan posisi fisik fastener/weld toe sebelum menyebutnya relevant."},{"heading":"Sizing & dokumentasi","body":"Length/area diambil dari extent indikasi pada C-scan (terkoreksi pitch dan encoder). Depth diestimasi dari phase angle dibanding kurva kalibrasi notch bertingkat. Catat: probe ID, frekuensi/mix, gain per channel, encoder resolution, overlap, reference block, dan screenshot C-scan + impedance plane. Level II bertanggung jawab atas interpretasi akhir, klasifikasi cacat, dan sign-off sesuai acceptance criteria."}]}', 480, NULL),
  (5, 'quiz', 'Mini-quiz — Array Probe Mastery', '{"description":"7 soal: konfigurasi & topologi coil, multiplexing, seleksi frekuensi, kalibrasi & channel balancing, strategi scan, dan interpretasi C-scan array probe Level II.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 3
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- ET-L2 Module 3 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'ET-L2' AND m."orderIndex" = 3 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'ET', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Mengapa array probe TIDAK mengaktifkan semua coil secara serentak, melainkan secara sequential (multiplexing)?',
   '["Untuk menghemat daya baterai instrument","Karena encoder hanya bisa membaca satu posisi pada satu waktu","Untuk mencegah cross-talk / induksi mutual antar coil yang berdekatan","Agar frekuensi tiap coil dapat berbeda secara permanen"]', 2,
   'Coil yang berdekatan akan saling menginduksi (cross-talk) jika dieksitasi serentak, sehingga mengotori sinyal. Multiplexer menyalakan coil secara sequential dalam time-slot mikrodetik agar tiap respons bersih dan dapat di-address ke posisi spasialnya. Prinsip akuisisi multi-coil ini dibakukan di ASTM E2884.', 'Array configuration', 'medium'),
  ('Pada aluminium (sigma ~40 %IACS, mu_r = 1) dengan frekuensi array 100 kHz, berapa perkiraan standard depth of penetration (delta) menggunakan delta ~ 21/sqrt(f*sigma*mu_r)?',
   '["Sekitar 0.33 mm","Sekitar 3.3 mm","Sekitar 0.033 mm","Sekitar 1.0 mm"]', 0,
   'delta = 21/sqrt(100*40*1) = 21/sqrt(4000) = 21/63.2 ~ 0.33 mm. Untuk surface crack pilih frekuensi tinggi (penetrasi dangkal, sensitif permukaan); turunkan frekuensi untuk cacat subsurface yang lebih dalam.', 'Frequency selection', 'medium'),
  ('Apa fungsi utama channel/gain balancing saat kalibrasi array probe?',
   '["Mempercepat scan dengan mematikan sebagian coil","Menyeragamkan respons amplitudo tiap coil agar tidak muncul banding palsu di C-scan","Mengubah orientasi sumbu sensitif probe terhadap cacat","Menaikkan frekuensi semua channel secara serentak"]', 1,
   'Tiap coil sedikit berbeda akibat toleransi manufaktur dan panjang jalur multiplexer. Channel balancing menormalkan gain tiap channel terhadap reflektor acuan sehingga responsnya seragam. Tanpa itu, C-scan menampilkan garis terang/gelap (banding) yang menyamar sebagai indikasi.', 'Calibration', 'medium'),
  ('Saat menyiapkan reference standard untuk kalibrasi array, mengapa block harus cukup lebar?',
   '["Agar dapat dipakai untuk single pencil probe juga","Untuk menambah massa block agar lebih stabil saat scan","Agar dapat diuji pada banyak frekuensi sekaligus","Agar SELURUH elemen array dapat melewati setiap reflektor acuan untuk verifikasi & balancing tiap channel"]', 3,
   'Per ASTM E2884, setiap coil harus diverifikasi merespons reflektor acuan secara seragam. Block harus cukup lebar agar semua elemen melewati tiap notch/FBH, sehingga balancing dan verifikasi sensitivitas per channel dapat dilakukan menyeluruh, bukan hanya pada sebagian coil.', 'Calibration', 'hard'),
  ('Teknik apa yang dipakai untuk menutup gap sensitivitas (dead zone) di antara coil tanpa memperkecil pitch fisik?',
   '["Menaikkan gain global hingga gap tidak terlihat","Menyusun coil dalam dua baris staggered (zig-zag) sehingga baris kedua menutup gap baris pertama","Menurunkan kecepatan scan secara drastis","Menambahkan satu single absolute coil di tengah probe"]', 1,
   'Coil di-stagger menjadi dua baris zig-zag; coil baris kedua menutupi gap baris pertama, secara efektif menggandakan resolusi lateral tanpa mengubah pitch fisik tiap baris. Menaikkan gain tidak mengisi zona sensitivitas rendah — hanya memperkuat noise.', 'Array configuration', 'hard'),
  ('Untuk mendeteksi crack axial tajam pada weld, kombinasi mode dan orientasi array yang paling tepat adalah:',
   '["Absolute coils dengan sumbu sensitif sejajar arah crack","Transmit-receive dengan probe diam tanpa encoder","Differential coils dengan sumbu sensitif tegak lurus (melintang) terhadap orientasi crack","Absolute coils dengan frekuensi serendah mungkin"]', 2,
   'Differential coils sangat peka pada perubahan tajam seperti crack dan menolak lift-off/drift. Sensitivitas maksimum tercapai ketika sumbu sensitif coil tegak lurus terhadap orientasi cacat sehingga aliran eddy current terpotong maksimal oleh crack.', 'Scan strategy', 'medium'),
  ('Pada C-scan array, banding seragam yang membentang di SELURUH lebar probe sejajar arah scan paling mungkin merupakan:',
   '["Crack memanjang nyata yang harus langsung di-reject tanpa evaluasi lanjut","Indikasi corrosion pit yang dalam dan terlokalisasi","Sinyal lift-off murni yang selalu berarti cacat","Artefak akibat channel imbalance / kalibrasi kurang sempurna, bukan cacat sebenarnya"]', 3,
   'Banding seragam yang konsisten di seluruh lebar dan sejajar arah scan biasanya berasal dari channel imbalance / normalisasi yang kurang sempurna, bukan cacat (cacat nyata bersifat lokal). Inspektor Level II harus kembali ke A-scan/impedance plane channel terkait untuk evaluasi sebenarnya sebelum dispositioning.', 'C-scan interpretation', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 3 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- ET-L2 Module 4 (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Bidang impedansi — peta semua sinyal ET', '{"slides":[{"heading":"Dua sumbu, satu peta","body":"Impedance plane menampilkan respon coil dalam dua komponen: sumbu horizontal = resistance (R), sumbu vertikal = inductive reactance (XL). Setiap perubahan kondisi di bawah probe (lift-off, crack, conductivity, ketebalan) menggeser titik operasi ke arah dan jarak tertentu. Level II membaca arah (phase angle) dan amplitudo sebagai dua informasi terpisah, bukan sekadar ''ada defleksi''. Catatan: layar modern biasanya menampilkan impedansi yang sudah dinormalisasi, sehingga posisi titik dapat dibandingkan antar probe/frekuensi."},{"heading":"Conductivity curve","body":"Pada surface coil, menaikkan conductivity material menggerakkan titik operasi turun menyusuri kurva berbentuk koma menuju ujung konduktivitas tinggi. Aluminium konduktivitas tinggi (Al murni ~61 %IACS; banyak paduan ~30-40 %IACS) berada lebih rendah pada kurva; titanium/stainless konduktivitas rendah (~1-3 %IACS) berada lebih tinggi pada kurva. Posisi vertikal (XL) inilah indikator paling andal — dasar conductivity sorting dan deteksi heat-treat/alloy mix-up: dua paduan berbeda jatuh di titik berbeda walau tampak identik secara visual."},{"heading":"Mengapa fase membawa kedalaman","body":"Eddy current di bawah permukaan tertinggal fase terhadap arus di permukaan: phase lag beta ~ x/delta radian, di mana delta = standard depth of penetration (skin depth), yaitu kedalaman tempat densitas eddy current turun ke 37% (1/e) dari nilai permukaan. delta = 1/sqrt(pi*f*mu*sigma). Untuk Al 100 kHz, sigma ~40 %IACS, mu_r=1, delta ~ 0.33 mm. Flaw yang lebih dalam mengalami rotasi fase lebih besar pada sinyalnya — inilah jembatan antara fisika skin depth dan orientasi loop di layar."},{"heading":"Frekuensi menggeser seluruh peta","body":"Menaikkan frekuensi memperkecil delta (bentuk praktis: delta[mm] ~ 21/sqrt(f[kHz]*sigma[%IACS]*mu_r)). Pada kurva impedansi ternormalisasi, menaikkan frekuensi menggeser titik operasi turun menyusuri kurva (arah yang sama dengan menaikkan conductivity) dan mengubah pemisahan fase antar sinyal. Level II memilih frekuensi bukan hanya untuk sensitivitas, tetapi untuk memaksimalkan sudut antara sinyal flaw dan lift-off sebelum kalibrasi — frekuensi yang salah membuat dua sinyal hampir kolinear dan mustahil dipisah."}]}', 460, NULL),
  (2, 'reading', 'Phase rotation — mengatur orientasi sinyal', '{"slides":[{"heading":"Apa yang dirotasi","body":"Phase rotation pada instrumen TIDAK mengubah fisika — ia hanya memutar tampilan vektor sinyal di layar agar orientasinya mudah dibaca. Konvensi industri: lift-off dibuat HORIZONTAL, sinyal flaw dibuat menonjol VERTIKAL. Setelah dirotasi, operator menilai defleksi vertikal sebagai indikasi flaw dan mengabaikan gerakan horizontal sebagai lift-off/probe wobble. Yang berubah hanyalah sudut acuan tampilan, bukan amplitudo maupun pemisahan fase intrinsik antar sinyal."},{"heading":"Prosedur kalibrasi fase","body":"1) Letakkan probe di material referensi, lalu null. 2) Angkat-turunkan probe untuk membangkitkan sinyal lift-off murni. 3) Putar phase control sampai trace lift-off jatuh horizontal (sepanjang sumbu X). Sekarang lift-off ''flat'' dan defek apa pun akan membentuk loop yang naik dari garis itu. Inilah baseline untuk semua interpretasi berikutnya; verifikasi pada calibration standard sebelum inspeksi aktual."},{"heading":"Phase angle = kedalaman flaw","body":"Pada eddy current tube/surface, sudut sinyal flaw terhadap arah lift-off menyandikan kedalaman/posisi. Konvensi umum bobbin: through-wall hole dipakai sebagai 100% reference dengan phase angle tertentu; defek OD (jauh dari coil) muncul mendekati arah lift-off (phase kecil), sedangkan defek ID/near-surface muncul dengan phase besar (mendekati vertikal). Operator membaca % wall loss dari phase angle dibandingkan kurva kalibrasi (calibration standard sesuai ASME V Article 8) — bukan dari amplitudo."},{"heading":"Mengapa amplitudo saja menipu","body":"Dua flaw bisa beramplitudo sama tetapi berbeda kedalaman: pit OD dangkal yang lebar versus crack ID sempit yang dalam. Amplitudo dipengaruhi volume material hilang DAN posisi (jarak ke coil); sebaliknya phase angle relatif independen terhadap ukuran/volume dan mendekati fungsi murni kedalaman/posisi. Karena itu Level II men-sizing dengan phase angle dan memakai amplitudo hanya sebagai cek sekunder/konfirmasi."}]}', 480, NULL),
  (3, 'reading', 'Lift-off vs flaw — memisahkan dengan fase', '{"slides":[{"heading":"Lift-off: musuh nomor satu","body":"Lift-off (jarak coil-ke-material berubah) menghasilkan sinyal BESAR yang bisa menenggelamkan flaw kecil. Kunci: lift-off dan flaw terpisah oleh PHASE ANGLE, bukan amplitudo. Pada permukaan, vektor lift-off menunjuk ke arah yang berbeda dari vektor flaw — pemisahan sudut inilah yang dieksploitasi instrumen melalui rotasi fase. Pemilihan frekuensi yang tepat memaksimalkan sudut pemisahan ini."},{"heading":"Setelah rotasi: baca komponen vertikal","body":"Begitu lift-off dibuat horizontal, defleksi murni horizontal = lift-off/wobble (diabaikan), sedangkan defleksi yang punya komponen vertikal = kandidat flaw. Probe wobble pada surface scan menjadi gerakan kiri-kanan datar; crack memberi loop yang ''memanjat'' dari sumbu. Operator melatih mata untuk menolak gerakan horizontal dan merespon defleksi vertikal."},{"heading":"Kapan rotasi tidak cukup — multi-frequency mixing","body":"Bila lift-off + support plate + flaw saling tumpang tindih (heat exchanger), rotasi fase satu frekuensi tidak cukup. Solusi: Channel A pada frekuensi defect-sensitive + Channel B sebagai reference (untuk lift-off/support plate), lalu mix A-B membatalkan sinyal yang tak diinginkan dan menyisakan sinyal defek. Tiga frekuensi (three-channel mixing) dipakai bila ada multiple support plates dengan geometri berbeda."},{"heading":"Fill factor & lift-off pada tube","body":"Pada bobbin/encircling, analog lift-off adalah fill factor (rasio diameter coil terhadap tube/ kerapatan kopling). Fill factor rendah = coupling lemah = sinyal flaw mengecil dan sinyal noise/geometri relatif membesar. Level II memverifikasi fill factor saat kalibrasi dan memakai mixing untuk menekan support-plate/dent signal agar phase-based sizing tetap valid."}]}', 460, NULL),
  (4, 'reading', 'Klasifikasi defek dari bentuk & fase sinyal', '{"slides":[{"heading":"Bentuk loop bercerita","body":"Pada differential bobbin, flaw lokal (pit) memberi sinyal figure-8 / dua-lobe yang relatif simetris saat coil masuk-keluar defek; gradual wall loss memberi respon lemah karena differential tidak peka pada perubahan bertahap. Absolute bobbin sebaliknya menangkap gradual wall thinning sebagai pergeseran baseline. Kombinasi absolute + differential membedakan pit lokal vs general/gradual corrosion."},{"heading":"OD vs ID — dari phase angle","body":"Pada tube, defek ID lebih dekat ke coil sehingga sinyalnya lebih besar dan phase angle-nya berbeda dari defek OD yang efeknya harus ''menembus'' wall (mengalami phase lag tambahan ~ x/delta). Memakai kurva kalibrasi (ASME V Art. 8) dari calibration standard (through-wall hole, flat-bottom holes, EDM notch berbagai kedalaman), operator membaca phase angle untuk menentukan kedalaman lalu mengklasifikasi asal (OD/ID) dan tipe defek."},{"heading":"Membedakan flaw dari artefak","body":"Support plate: sinyal besar, fase khas, posisi tetap di lokasi tube sheet/baffle — dikenali dan dapat di-mix-out. Dent/ding: respon lift-off-like, fase mendekati horizontal setelah kalibrasi. Magnetic deposit/inclusion (mis. sludge atau partikel ferromagnetik): respon ke arah permeability dan sering off-axis. Level II memilah artefak ini sebelum melaporkan agar tidak over-call atau under-call."},{"heading":"Keputusan & sign-off","body":"Klasifikasi akhir menggabungkan: phase angle (kedalaman & OD/ID), amplitudo (cek volume), bentuk loop (lokal vs gradual), dan posisi (dekat support plate?). Reject/accept berdasarkan acceptance criteria prosedur (mis. melebihi batas % wall loss). Sebagai Level II Anda menandatangani interpretasi — dokumentasikan frekuensi, mix, kalibrasi/standar referensi, dan reasoning klasifikasi, bukan sekadar ''reject/accept''."}]}', 500, NULL),
  (5, 'quiz', 'Mini-quiz — Complex impedance plane analysis', '{"description":"7 soal: fundamental bidang impedansi, phase rotation, pemisahan lift-off vs flaw, mixing, dan klasifikasi defek dari fase/bentuk sinyal.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 4
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- ET-L2 Module 4 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'ET-L2' AND m."orderIndex" = 4 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'ET', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada impedance plane standar, apa yang diwakili sumbu horizontal dan sumbu vertikal?',
   '["Horizontal = inductive reactance (XL), vertikal = resistance (R)","Horizontal = resistance (R), vertikal = inductive reactance (XL)","Horizontal = frekuensi, vertikal = amplitudo sinyal","Horizontal = phase angle, vertikal = lift-off distance"]', 1,
   'Impedance plane memetakan respon coil dengan sumbu horizontal = resistance (R) dan sumbu vertikal = inductive reactance (XL). Setiap perubahan kondisi menggeser titik operasi pada bidang R-XL ini.', 'Impedance Plane Fundamentals', 'easy'),
  ('Pada surface coil, ke arah mana titik operasi bergerak pada kurva konduktivitas (comma curve) ketika conductivity material dinaikkan?',
   '["Naik menjauhi ujung konduktivitas tinggi","Turun menyusuri kurva menuju ujung konduktivitas tinggi","Tetap di tempat; hanya amplitudo yang berubah","Bergerak horizontal murni tanpa perubahan reactance"]', 1,
   'Menaikkan conductivity menggerakkan titik operasi turun menyusuri kurva berbentuk koma menuju ujung konduktivitas tinggi (XL lebih rendah). Posisi vertikal pada kurva inilah dasar conductivity sorting dan deteksi alloy/heat-treat mix-up.', 'Impedance Plane Fundamentals', 'medium'),
  ('Saat instrumen melakukan phase rotation untuk membuat lift-off horizontal, apa yang sebenarnya berubah?',
   '["Fisika eddy current di bawah probe berubah sehingga lift-off hilang","Frekuensi operasi otomatis dinaikkan untuk menekan lift-off","Hanya orientasi tampilan vektor sinyal di layar yang diputar; fisikanya tidak berubah","Amplitudo sinyal flaw diperbesar dan amplitudo lift-off dikecilkan"]', 2,
   'Phase rotation hanya memutar tampilan vektor sinyal di layar agar mudah dibaca (lift-off dibuat horizontal, flaw vertikal). Fisika eddy current, amplitudo, dan pemisahan fase intrinsik tidak berubah — yang berubah hanya sudut acuan penyajian.', 'Phase Rotation', 'medium'),
  ('Mengapa Level II men-sizing kedalaman flaw dari phase angle, bukan dari amplitudo sinyal?',
   '["Amplitudo tidak bisa diukur pada instrumen modern","Phase angle relatif independen dari ukuran/volume dan mendekati fungsi murni kedalaman/posisi, sedangkan amplitudo dipengaruhi volume material hilang DAN posisi","Amplitudo selalu nol untuk flaw yang dalam","Phase angle tidak terpengaruh oleh frekuensi sehingga selalu lebih mudah dibaca"]', 1,
   'Dua flaw bisa beramplitudo sama tapi berbeda kedalaman karena amplitudo dipengaruhi volume material hilang DAN jarak ke coil. Phase angle relatif independen dari ukuran/volume dan mendekati fungsi murni kedalaman/posisi (beta ~ x/delta), sehingga lebih andal untuk sizing.', 'Defect Sizing', 'hard'),
  ('Setelah kalibrasi membuat lift-off horizontal, defleksi sinyal seperti apa yang menandai kandidat flaw?',
   '["Defleksi murni horizontal sepanjang sumbu X","Defleksi yang memiliki komponen vertikal (memanjat dari garis lift-off)","Tidak ada defleksi sama sekali","Defleksi yang amplitudonya kecil saja, tanpa memperhatikan arah"]', 1,
   'Begitu lift-off dibuat horizontal, gerakan murni horizontal = lift-off/probe wobble (diabaikan). Defleksi yang memiliki komponen vertikal (memanjat dari garis lift-off) adalah kandidat flaw.', 'Lift-off vs Flaw', 'medium'),
  ('Pada heat exchanger di mana sinyal lift-off, support plate, dan flaw saling tumpang tindih, teknik apa yang melengkapi phase rotation satu frekuensi?',
   '["Menurunkan gain hingga support plate hilang","Multi-frequency mixing: Channel A frekuensi defect-sensitive + Channel B reference, lalu mix A-B membatalkan sinyal yang tak diinginkan","Mengganti bobbin dengan surface pencil probe","Menaikkan fill factor hingga melebihi 100%"]', 1,
   'Bila lift-off + support plate + flaw tumpang tindih, rotasi fase satu frekuensi tidak cukup. Multi-frequency mixing (Channel A defect-sensitive + Channel B reference, mix A-B) membatalkan sinyal support-plate/lift-off; tiga frekuensi dipakai untuk multiple support plates dengan geometri berbeda.', 'Signal Separation', 'hard'),
  ('Pada inspeksi tube dengan bobbin, bagaimana defek ID umumnya dibedakan dari defek OD?',
   '["Defek ID selalu memberi amplitudo nol","Defek ID lebih dekat ke coil sehingga sinyalnya lebih besar dan phase angle-nya berbeda dari defek OD yang efeknya harus menembus dinding (phase lag tambahan)","Defek OD selalu muncul horizontal setelah kalibrasi","Tidak ada cara membedakan OD dan ID dengan eddy current"]', 1,
   'Defek ID lebih dekat ke coil sehingga sinyalnya lebih besar dan phase angle-nya berbeda dibanding defek OD yang harus menembus seluruh dinding (mengalami phase lag tambahan ~ x/delta). Dengan kurva kalibrasi ASME V Art. 8 dari calibration standard, phase angle dibaca untuk menentukan kedalaman dan asal (OD/ID).', 'Defect Classification', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 4 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- ET-L2 Module 5 — Heat Exchanger Inspection — Advanced (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Memilih metode tube: kapan bobbin tidak cukup', '{"slides":[{"heading":"Batas conventional bobbin ET","body":"Bobbin probe (absolute & differential) adalah workhorse untuk tube non-ferromagnetik (Cu, brass, Cu-Ni, titanium, austenitic stainless 300-series, Inconel). Sangat cepat (sampai ~1 m/s pull rate) dan sensitif terhadap pit OD/ID serta wall loss volumetrik. Namun bobbin praktis BUTA terhadap material ferromagnetik (carbon steel, ferritic/martensitic stainless): permeabilitas tinggi meruntuhkan penetrasi eddy current ke permukaan ID sekaligus menimbulkan permeability noise, sehingga defek OD tidak terdeteksi. Bobbin juga lemah pada crack circumferential (sejajar lilitan coil) dan sizing-nya menurun pada defek tepat di bawah support plate."},{"heading":"Skin depth menjelaskan keterbatasannya","body":"Standard depth of penetration (skin depth) adalah kedalaman di mana densitas eddy current turun ke 37% (1/e): delta ~ 21/sqrt(f[kHz]*sigma[%IACS]*mu_r). Acuan: aluminium 100 kHz, sigma ~40 %IACS, mu_r=1 -> delta ~ 0.33 mm. Pada material ferromagnetik mu_r bisa 50-200, sehingga delta runtuh ke skala puluhan mikron — eddy current konvensional tidak pernah menembus ke dinding OD. Itulah alasan fundamental conventional ET gagal pada carbon steel tube, dan mengapa RFT (yang TIDAK mengandalkan penetrasi skin-depth langsung) atau IRIS (ultrasonik) diperlukan untuk tube ferromagnetik."},{"heading":"Matriks pemilihan metode","body":"Aturan praktis Level II: (1) Tube NON-ferro, cari pit/wall loss cepat -> conventional bobbin ET. (2) Tube FERRO (carbon steel, ferritic SS), butuh deteksi keliling penuh throughput sedang -> RFT. (3) Butuh wall thickness ABSOLUT akurat (mapping korosi, baseline) tanpa peduli material -> IRIS (ultrasonik). (4) Tube ferro, kecepatan tinggi, fin-fan/air cooler bundle -> MFL. (5) Crack ID kecil pada non-ferro / butuh imaging C-scan -> array probe."},{"heading":"Sifat material yang menentukan","body":"Sebelum memilih, Level II HARUS mengetahui: material tube (cek mill cert / conductivity sorting %IACS), apakah ferromagnetik (uji magnet sederhana), diameter & wall thickness (untuk fill factor encircling/bobbin dan probe sizing), serta konfigurasi support plate dan tube sheet. Untuk tube yang sebagian magnetik (mis. duplex, atau 400-series yang termagnetisasi sebagian, U-bend austenitic yang ter-cold-work), RFT atau saturation-ET dengan kalibrasi yang tepat lebih reliabel daripada memaksa bobbin konvensional."}]}', 460, NULL),
  (2, 'reading', 'RFT — Remote Field Testing untuk tube ferromagnetik', '{"slides":[{"heading":"Prinsip through-transmission","body":"RFT menggunakan probe ID dengan exciter coil dan detector coil yang dipisahkan ~2-3 kali diameter tube. Energi tidak menembus dinding secara langsung (skin depth runtuh pada ferro), melainkan medan exciter menjalar SEPANJANG dinding lalu kembali masuk ke ID di lokasi detector — disebut remote field zone. Karena medan melewati dinding DUA kali (keluar lalu masuk lagi), RFT memberi sensitivitas yang HAMPIR SAMA untuk defek OD maupun ID — kelebihan besar dibanding conventional ET yang bias ke ID."},{"heading":"Phase = depth, frekuensi rendah","body":"Pada remote field zone, pergeseran fasa sinyal sebanding dengan total path melalui dinding, sehingga PHASE LAG menjadi indikator wall loss utama (semakin dalam/banyak wall loss -> semakin besar phase shift) — bukan amplitudo. RFT beroperasi pada frekuensi RENDAH (tipikal puluhan hingga ratusan Hz, mis. ~30-500 Hz), jauh di bawah conventional ET yang kHz-an, agar medan dapat menjangkau seluruh dinding ferro. Kalibrasi dibuat pada tube referensi dengan groove/flat-bottom hole bertingkat untuk membangun phase-vs-depth curve."},{"heading":"Karakteristik & keterbatasan","body":"Kelebihan: penetrasi full wall, sensitivitas OD ~ ID setara, baik untuk general/gradual wall loss pada tube ferro. Keterbatasan: lebih lambat dari bobbin, resolusi untuk pitting tajam/defek kecil lebih rendah, dan SANGAT terpengaruh fitur dinding rangkap (tube sheet, support plate, U-bend) yang memberi sinyal mirip wall loss. Level II harus mengenali support-plate signature sebagai landmark, bukan salah-klasifikasi sebagai korosi."},{"heading":"Standar & aplikasi","body":"Aplikasi tipikal: boiler tube ferritic, feedwater heater, carbon-steel heat exchanger, dan air-cooler bundle ferromagnetik. Referensi utama: ASTM E2096 (RFT pada ferromagnetic heat-exchanger tube). Untuk tube austenitic yang sebagian termagnetisasi (cold work pada U-bend), RFT dapat dipakai bila bobbin terganggu permeabilitas lokal. Pelaporan menyatakan % wall loss berbasis PHASE (phase-vs-depth curve), bukan amplitudo."}]}', 500, NULL),
  (3, 'reading', 'IRIS & MFL — ultrasonik dan flux leakage', '{"slides":[{"heading":"IRIS — Internal Rotary Inspection System","body":"IRIS adalah metode ULTRASONIK, bukan elektromagnetik. Probe ID berisi transducer dan mirror berputar (turbine-driven oleh aliran air) yang membelokkan pulsa UT ke seluruh keliling dinding. Time-of-flight echo OD-ID memberi WALL THICKNESS ABSOLUT yang akurat (resolusi ~0.025 mm). IRIS bekerja pada material APA SAJA (ferro maupun non-ferro) karena UT tidak bergantung pada permeabilitas/konduktivitas. Inilah metode pilihan untuk baseline wall mapping dan verifikasi/konfirmasi sizing temuan ET/RFT."},{"heading":"Trade-off IRIS","body":"Harga dari akurasi adalah KECEPATAN dan kondisi: IRIS sangat LAMBAT (perlu rotasi & pemindaian helical), butuh WATER COUPLING (tube terendam/dialiri air bersih sebagai media perambat UT), dan menuntut ID yang BERSIH (scale/fouling memantulkan/meredam UT dan merusak data). Karena lambat, IRIS umumnya dipakai sebagai metode KONFIRMASI pada subset tube yang sudah disaring cepat oleh bobbin/RFT (strategi 100% ET screening + IRIS pada flagged tubes)."},{"heading":"MFL — Magnetic Flux Leakage untuk tube","body":"MFL memagnetisasi dinding tube ferromagnetik hingga mendekati saturasi; pada lokasi wall loss, fluks ''bocor'' keluar dari permukaan dan dideteksi sensor Hall/coil. MFL CEPAT dan baik untuk pitting serta general wall loss volumetrik pada carbon-steel tube (mis. fin-fan air cooler). Amplitudo leakage berkorelasi dengan volume metal loss, tetapi MFL kurang akurat untuk sizing kedalaman absolut dan kurang sensitif terhadap crack sempit yang sejajar arah magnetisasi. MFL TIDAK berlaku pada tube non-ferromagnetik."},{"heading":"Memadukan metode di lapangan","body":"Praktik Level II umum: skrining cepat seluruh bundle (bobbin untuk non-ferro / RFT atau MFL untuk ferro), lalu KONFIRMASI tube yang dicurigai dengan IRIS untuk sizing absolut sebelum keputusan plug/retube. Untuk eddy current pada tube ferromagnetik, ASTM E309 mensyaratkan MAGNETIC SATURATION agar permeabilitas variabel tidak mengacaukan sinyal (saturation-eddy-current); kalibrasi dan inspeksi harus dilakukan pada kondisi saturasi yang sama agar respons material konsisten."}]}', 500, NULL),
  (4, 'reading', 'Kalibrasi, data management & pelaporan bundle', '{"slides":[{"heading":"Reference tube & kalibrasi","body":"Setiap metode butuh reference standard dari material, OD, dan wall yang SAMA dengan tube produksi. Bobbin/saturation-ET: ASME V Article 8 menetapkan through-wall hole dan flat-bottom hole/groove (mis. set drilled holes plus OD/ID groove bertingkat) untuk men-set phase dan sensitivitas. RFT: groove bertingkat untuk membangun phase-vs-depth curve. IRIS: verifikasi kalibrasi velocity & gate pada step wedge atau tube referensi berdimensi diketahui. Kalibrasi diverifikasi ulang pada interval waktu tertentu dan setiap ganti probe/kabel/instrumen."},{"heading":"Support plate & tube sheet","body":"Sinyal support plate (carbon steel) dan tube sheet adalah artefak terbesar pada inspeksi bundle. Pada bobbin tube non-ferro gunakan multi-frequency mixing: satu channel dijadikan referensi support-plate sehingga proses mix (A-B) mengkanselkan signature plate dan defek di BAWAH plate tetap terlihat. Pada RFT, support plate memberi phase shift mirip wall loss — operator harus memetakan posisi plate dari konstruksi exchanger dan mengoreksi/mengabaikan sinyal pada landmark tersebut."},{"heading":"Landmark, indexing & C-scan","body":"Data tube di-index dari tube sheet (entry) sehingga posisi aksial setiap indikasi dapat dilaporkan presisi. Array probe menghasilkan C-scan (peta keliling x aksial) yang memvisualkan sebaran pitting, crack circumferential, dan wall-loss patch — sesuai ASTM E2884. Setiap tube dicatat dengan ID baris-kolom pada tube sheet map; tube yang di-plug/retube ditandai pada peta agar histori bundle terlacak antar shutdown."},{"heading":"Pelaporan & keputusan fitness","body":"Laporan menyatakan % wall loss maksimum per tube, tipe defek (pit, wall loss, crack, baffle cut/wear, erosion), lokasi (jarak dari tube sheet dan jam keliling), serta metode yang dipakai. Threshold plug ditentukan kriteria pelanggan/RBI (umum: plug bila wall loss melampaui ambang mis. 50-60% atau ada through-wall). Indikasi marginal dari ET/RFT dikonfirmasi IRIS sebelum tube dinyatakan reject — sign-off sizing adalah tanggung jawab Level II."}]}', 470, NULL),
  (5, 'quiz', 'Mini-quiz — Heat Exchanger Inspection (RFT/IRIS/MFL)', '{"description":"8 soal pemilihan metode, prinsip RFT/IRIS/MFL, skin depth, kalibrasi, dan pelaporan bundle untuk tube heat exchanger.","questionCount":8,"passingScore":75}', 680, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 5
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- ET-L2 Module 5 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'ET-L2' AND m."orderIndex" = 5 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'ET', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Sebuah heat exchanger menggunakan tube carbon steel (ferromagnetik). Mengapa conventional bobbin ET gagal mendeteksi wall loss di sisi OD tube ini?',
   '["Karena permeabilitas tinggi meruntuhkan skin depth sehingga eddy current tidak menembus sampai dinding OD","Karena carbon steel terlalu konduktif sehingga sinyal terlalu kuat dan men-saturasi amplifier","Karena bobbin probe hanya bisa dipakai pada tube berdiameter besar","Karena frekuensi bobbin terlalu rendah untuk material magnetik"]', 0,
   'Pada material ferromagnetik mu_r tinggi (puluhan hingga ratusan). Karena delta ~ 21/sqrt(f*sigma*mu_r), kenaikan mu_r meruntuhkan skin depth ke skala puluhan mikron, sehingga eddy current terkonsentrasi di permukaan ID dan tidak pernah mencapai dinding OD. Sebagai pembanding, Al pada 100 kHz (sigma ~40 %IACS, mu_r=1) hanya punya delta ~0.33 mm — pada ferro delta jauh lebih kecil. Itu sebabnya digunakan RFT atau IRIS untuk tube ferro.', 'Skin Depth & Theory', 'medium'),
  ('Pada RFT, parameter sinyal apa yang menjadi indikator utama kedalaman/derajat wall loss?',
   '["Amplitudo lift-off pada sumbu horizontal","Phase lag (pergeseran fasa) yang bertambah seiring bertambahnya wall loss","Frekuensi resonansi coil detector","Perubahan resistansi DC pada exciter coil"]', 1,
   'Di remote field zone, pergeseran fasa sebanding dengan total path melalui dinding, sehingga phase lag menjadi indikator wall loss utama (semakin dalam/banyak wall loss, semakin besar phase shift), bukan amplitudo. Karena itu kalibrasi RFT membangun phase-vs-depth curve dari groove bertingkat pada reference tube.', 'RFT', 'medium'),
  ('Apa keunggulan utama RFT (Remote Field Testing) dibanding conventional eddy current pada inspeksi tube ferromagnetik?',
   '["Kecepatan scan jauh lebih tinggi daripada bobbin pada tube non-ferro","Tidak memerlukan reference standard sama sekali","Sensitivitas terhadap defek OD dan ID hampir setara karena medan melewati dinding dua kali (through-transmission)","Mampu mengukur wall thickness absolut lebih akurat daripada IRIS"]', 2,
   'RFT memakai exciter dan detector terpisah ~2-3 diameter tube; medan menjalar sepanjang dinding lalu kembali masuk ke ID, melewati dinding dua kali. Hasilnya sensitivitas OD dan ID nyaris setara — keunggulan kunci RFT pada tube ferro. RFT justru lebih lambat dari bobbin dan kurang akurat untuk sizing absolut dibanding IRIS (ultrasonik).', 'RFT', 'medium'),
  ('Mengapa IRIS sering dipakai sebagai metode KONFIRMASI pada subset tube, bukan untuk skrining 100% bundle?',
   '["Karena IRIS hanya berfungsi pada tube non-ferromagnetik","Karena IRIS tidak dapat mengukur wall thickness absolut","Karena IRIS hanya mendeteksi crack dan buta terhadap wall loss","Karena IRIS sangat akurat tetapi lambat, butuh water coupling, dan menuntut ID yang bersih"]', 3,
   'IRIS adalah metode ultrasonik yang memberi wall thickness absolut sangat akurat pada material apa pun (ferro maupun non-ferro), tetapi rotasi/pemindaian helical-nya lambat, memerlukan water coupling sebagai media perambat UT, dan ID harus bersih dari scale. Strateginya: skrining cepat dengan bobbin/RFT lalu konfirmasi tube yang di-flag dengan IRIS untuk sizing absolut sebelum keputusan plug.', 'IRIS', 'medium'),
  ('Manakah pernyataan yang BENAR membedakan IRIS dari metode elektromagnetik (ET/RFT/MFL)?',
   '["IRIS berbasis ultrasonik (time-of-flight), sehingga akurasinya tidak bergantung pada permeabilitas atau konduktivitas material","IRIS adalah varian eddy current frekuensi sangat rendah yang khusus untuk tube ferro","IRIS mengukur kebocoran fluks magnetik dengan sensor Hall","IRIS mengandalkan phase lag eddy current untuk menghitung kedalaman defek"]', 0,
   'IRIS (Internal Rotary Inspection System) memakai transducer UT dan mirror berputar; time-of-flight echo OD-ID memberi wall thickness absolut. Karena ultrasonik, IRIS bekerja pada material apa pun dan tidak terpengaruh permeabilitas/konduktivitas — berbeda dari ET/RFT (eddy current, phase) dan MFL (kebocoran fluks magnetik, sensor Hall).', 'IRIS', 'easy'),
  ('MFL (Magnetic Flux Leakage) untuk tube paling tepat digunakan pada kondisi berikut:',
   '["Tube austenitic stainless non-magnetik untuk crack sizing presisi","Tube ferromagnetik (mis. carbon steel air cooler) untuk deteksi cepat pitting dan general wall loss volumetrik","Tube titanium tipis untuk pengukuran wall thickness absolut","Tube tembaga untuk deteksi crack longitudinal halus"]', 1,
   'MFL memagnetisasi dinding ferro mendekati saturasi; pada wall loss fluks bocor keluar dan dideteksi sensor Hall/coil. MFL cepat dan baik untuk pitting/general wall loss volumetrik pada tube carbon steel, tetapi kurang akurat untuk sizing kedalaman absolut dan lemah pada crack sempit sejajar arah magnetisasi. Pada material non-ferromagnetik MFL tidak berlaku.', 'MFL', 'easy'),
  ('Saat memeriksa tube heat exchanger non-ferro dengan bobbin, sinyal support plate dapat menutupi defek di bawahnya. Teknik apa yang tepat untuk mengatasinya?',
   '["Menaikkan kecepatan tarik probe agar sinyal plate tidak sempat terekam","Multi-frequency mixing dengan channel referensi yang mengkanselkan signature support plate","Mengganti bobbin dengan pencil/surface probe","Menonaktifkan kalibrasi fasa agar semua sinyal tampil vertikal"]', 1,
   'Support plate carbon steel memberi sinyal besar. Dengan multi-frequency mixing, satu channel dijadikan referensi support-plate; proses mix (A-B) mengkanselkan signature plate sehingga defek di bawah plate tetap terlihat. Ini teknik standar bobbin inspection pada bundle dengan banyak support plate. Menaikkan kecepatan justru memperburuk; pencil probe untuk permukaan, bukan ID tube.', 'Calibration & Data', 'medium'),
  ('Menurut ASTM E309, mengapa magnetic saturation diperlukan saat melakukan eddy current pada tube ferromagnetik?',
   '["Untuk meningkatkan konduktivitas tube sehingga skin depth bertambah dalam","Untuk menghilangkan kebutuhan akan reference standard","Agar permeabilitas variabel material tidak mengacaukan sinyal eddy current, dengan kalibrasi pada kondisi saturasi yang sama","Agar tube dapat diperiksa tanpa probe ID"]', 2,
   'Pada tube ferromagnetik, permeabilitas yang bervariasi (akibat cold work, tegangan, komposisi) menimbulkan noise yang mengaburkan sinyal defek. ASTM E309 mensyaratkan magnetisasi mendekati saturasi sehingga mu efektif menjadi konsisten/rendah; kalibrasi dan inspeksi harus dilakukan pada kondisi saturasi yang sama agar respons material dapat diandalkan. Saturasi tidak mengubah konduktivitas maupun menghapus kebutuhan reference standard.', 'Codes & Standards', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 5 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- ET-L2 Module 6 (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'ET di dunia aerospace — kenapa kritis', '{"slides":[{"heading":"Konteks aerospace","body":"Struktur pesawat (aluminium alloy 2024-T3, 7075-T6, titanium, baja landing gear) menanggung ribuan fatigue cycle per flight. ET adalah metode utama untuk deteksi fatigue crack dini di area kritis — terutama di sekitar fastener hole, tempat stress concentration paling tinggi. Standar acuan: ASTM E2096 (in-service eddy current pada struktur aerospace), NAS410/EN4179 untuk sertifikasi personel."},{"heading":"Tiga aplikasi inti Level II","body":"Level II ET aerospace fokus pada tiga tugas: (1) inspeksi fastener hole dengan rotating/bolt-hole probe, (2) deteksi surface/skin crack pada lap joint dan fuselage skin, dan (3) conductivity sorting untuk verifikasi alloy/temper, heat-treat, dan deteksi heat damage. Inspektor Level II memilih teknik, melakukan set up kalibrasi, dan menandatangani interpretasi sesuai prosedur."},{"heading":"Keunggulan ET untuk Al alloy","body":"Aluminium non-ferromagnetik (mu_r=1) dengan konduktivitas tinggi — ideal untuk ET. Standard depth of penetration (skin depth, delta) adalah kedalaman tempat densitas eddy current turun ke 37% (1/e) nilai permukaan. Bentuk praktis: delta[mm] ~ 21/sqrt(f[kHz]*sigma[%IACS]*mu_r). Anchor: Al 100 kHz, sigma ~40 %IACS, mu_r=1 -> delta ~ 21/sqrt(100*40*1) ~ 0.33 mm. delta MENGECIL saat frekuensi, konduktivitas, atau permeabilitas naik."},{"heading":"Memilih frekuensi & disiplin prosedural","body":"Frekuensi diatur agar crack target berada dalam ~1-3 skin depth dari permukaan scan. Surface crack di skin dangkal -> frekuensi tinggi (200 kHz-2 MHz); subsurface/second-layer crack -> frekuensi rendah (1-10 kHz). Setiap inspeksi mengacu ke specific procedure (mis. NDT Manual OEM Boeing/Airbus) yang menyebut probe part number, frekuensi, reference standard, dan reject criteria. Level II tidak boleh menyimpang tanpa engineering disposition; reference standard biasanya EDM notch terkalibrasi (mis. 0.5 mm, 1.0 mm)."}]}', 440, NULL),
  (2, 'reading', 'Inspeksi fastener hole — rotating probe', '{"slides":[{"heading":"Masalah fastener hole","body":"Bore (dinding lubang) fastener adalah lokasi fatigue crack nomor satu di airframe: cold-work, interference fit, dan cyclic load memusatkan stress di sini. Crack tumbuh radial dari bore. Dua teknik utama: bolt-hole eddy current (BHEC) dengan rotating probe untuk fastener yang DILEPAS, dan low-frequency sliding/ring probe untuk inspeksi TANPA melepas fastener (crack di second/third layer)."},{"heading":"Rotating (bolt-hole) probe","body":"Probe absolut atau differential dipasang di mandrel yang berputar (manual atau motorized scanner) sambil bergerak aksial sepanjang bore, menghasilkan helical scan path yang men-scan keliling 360 derajat. Crack radial memotong eddy current dan muncul sebagai sinyal vertikal di impedance plane. Frekuensi tipikal 100-200 kHz untuk Al; diameter probe dipilih agar fill factor pas (clearance kecil, lift-off minimal dan konstan)."},{"heading":"Kalibrasi & set up","body":"Gunakan reference ring/coupon dengan EDM notch (mis. 0.030 in / 0.76 mm dalam) pada diameter lubang yang sama dengan part. Putar phase agar lift-off horizontal dan sinyal notch vertikal, lalu set amplitudo notch ke ~80% FSH. Null-kan probe di area bersih bore. Reject criteria: setiap indikasi >= amplitudo notch reference dianggap relevan dan harus dievaluasi serta di-disposition sesuai prosedur."},{"heading":"Layered structure & second-layer crack","body":"Untuk crack pada layer kedua di sekitar fastener tanpa melepas fastener, turunkan frekuensi (1-10 kHz) agar penetrasi mencapai layer bawah — ingat skin depth bertambah saat frekuensi turun. Gunakan sliding probe atau ring probe. Tantangan: sinyal dari fastener (steel/titanium) dan edge effect besar; multi-frequency mixing dipakai untuk cancel sinyal fastener/support dan menonjolkan sinyal crack."}]}', 480, NULL),
  (3, 'reading', 'Skin crack & surface inspection', '{"slides":[{"heading":"Surface crack pada skin","body":"Fuselage skin, wing skin, dan doubler rentan terhadap fatigue crack permukaan dan korosi. Surface (pencil/pancake) probe dengan frekuensi tinggi (200 kHz-2 MHz) memberi resolusi tinggi untuk crack dangkal. Crack permukaan memutus arus eddy -> deflection vertikal kuat. Frekuensi tinggi -> skin depth dangkal -> sensitif ke crack tepat di permukaan dan kurang terganggu sinyal sub-surface."},{"heading":"Lift-off — musuh utama","body":"Pada permukaan bercat/primer, lift-off besar dan dapat menutupi crack kecil. Lift-off dan flaw terpisah berdasarkan PHASE ANGLE; instrumen dirotasi phase agar lift-off horizontal dan crack vertikal, sehingga operator dapat membedakan keduanya. Conductive shim atau probe spring-loaded menjaga lift-off konstan. Cat tebal (>0.1 mm) menurunkan sensitivitas — mungkin perlu paint removal atau frekuensi lebih rendah."},{"heading":"Edge effect & fastener noise","body":"Tepi panel dan deretan fastener menghasilkan sinyal besar yang menyerupai crack. Scan paralel terhadap rivet row, gunakan sliding probe khusus rivet, atau array probe untuk membedakan crack dari geometry. Crack di sekitar countersink fastener (faying surface) adalah skenario sulit — sering butuh frekuensi rendah plus multi-frequency mixing untuk cancel sinyal geometry/fastener."},{"heading":"Array probe & C-scan imaging","body":"Eddy current array (ECA, ASTM E2884) memakai banyak coil yang dimultipleks untuk coverage lebar dalam satu pass dan menghasilkan C-scan image. Untuk skin/lap joint, ECA mempercepat inspeksi area besar serta memberi peta visual crack dan corrosion thinning, mengurangi human factor dibanding raster manual single coil. Kalibrasi dan phase rotation tetap diperlukan."}]}', 460, NULL),
  (4, 'reading', 'Conductivity sorting & heat damage', '{"slides":[{"heading":"Apa itu conductivity sorting","body":"Konduktivitas (diukur dalam %IACS) sensitif terhadap komposisi alloy dan kondisi heat-treat/temper. Conductivity meter ET (absolute coil, frekuensi tetap mis. 60 kHz) dikalibrasi dengan dua reference standard yang mengapit (bracketing) nilai target, mis. 30 %IACS dan 50 %IACS, agar pembacaan linear di rentang itu. Aplikasi: verifikasi alloy mix-up, deteksi heat damage, dan pengukuran tebal coating non-konduktif."},{"heading":"Heat damage detection","body":"Aluminium yang terkena overheat (fire, lightning strike, over-aging) berubah temper sehingga konduktivitasnya NAIK. Contoh 7075-T6 punya rentang acceptance tipikal ~30.5-36 %IACS; pembacaan yang melewati batas atas (mis. ~38 %IACS) mengindikasikan over-aging/heat damage dengan kemungkinan kehilangan kekuatan. Inspektor memetakan grid pembacaan untuk menentukan batas zona heat-affected sebelum repair disposition. Selalu rujuk tabel acceptance prosedur/OEM, bukan satu angka tunggal."},{"heading":"Faktor yang mempengaruhi pembacaan","body":"Lift-off, suhu, edge effect, dan kelengkungan part mempengaruhi conductivity reading. Selalu null pada part class yang sama, jaga probe tegak lurus (minimalkan lift-off), dan kompensasi suhu — konduktivitas logam TURUN saat suhu naik, jadi reading harus dikoreksi ke suhu referensi. Sebagian instrumen punya lift-off compensation hingga ~0.1 mm. Standar acuan: ASTM E1004 (electromagnetic conductivity)."},{"heading":"Coating thickness","body":"Pada substrat konduktif dengan coating non-konduktif (cat/anodize), lift-off sebanding dengan tebal coating. Setelah dikalibrasi terhadap shim ketebalan diketahui, ET dapat mengukur tebal coating. Ini mengubah efek lift-off yang biasanya merugikan menjadi pengukuran berguna — banyak dipakai untuk QC paint/anodize aerospace. Catatan: metode ini hanya valid untuk coating non-konduktif di atas substrat konduktif."}]}', 460, NULL),
  (5, 'quiz', 'Mini-quiz — Aerospace ET applications', '{"description":"7 soal aplikasi aerospace: fastener hole, skin crack, dan conductivity sorting Level II.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 6
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- ET-L2 Module 6 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'ET-L2' AND m."orderIndex" = 6 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'ET', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Lokasi paling umum inisiasi fatigue crack pada struktur airframe adalah:',
   '["Bore (dinding) fastener hole","Tengah panel skin yang datar","Permukaan cat luar","Stringer yang tidak ber-load"]', 0,
   'Fastener hole adalah lokasi stress concentration tertinggi; crack tumbuh radial dari bore akibat cyclic load dan interference fit. Karena itu inspeksi bolt-hole eddy current menjadi tugas inti Level II aerospace.', 'aerospace', 'easy'),
  ('Pada bolt-hole eddy current (BHEC) dengan rotating probe, crack radial pada bore muncul di impedance plane sebagai:',
   '["Pergeseran DC offset saja","Sinyal vertikal yang terpisah dari lift-off","Sinyal horizontal sejajar lift-off","Tidak ada sinyal sama sekali"]', 1,
   'Instrumen dirotasi phase agar lift-off horizontal dan sinyal crack vertikal. Crack radial memotong eddy current dan menghasilkan deflection vertikal yang terpisah secara phase angle dari lift-off.', 'fastener-hole', 'medium'),
  ('Untuk mendeteksi crack pada layer KEDUA di sekitar fastener TANPA melepas fastener, frekuensi yang dipilih sebaiknya:',
   '["Dinaikkan agar resolusi permukaan maksimal","Dibuat sama dengan frekuensi surface crack","Diturunkan agar penetrasi mencapai layer bawah","Tidak berpengaruh terhadap penetrasi"]', 2,
   'Skin depth bertambah saat frekuensi turun (delta = 1/sqrt(pi*f*mu*sigma)). Crack di layer kedua butuh penetrasi lebih dalam, jadi gunakan frekuensi rendah (1-10 kHz) plus mixing untuk cancel sinyal fastener.', 'fastener-hole', 'hard'),
  ('Untuk deteksi surface crack DANGKAL pada fuselage skin aluminium, pilihan frekuensi dan probe yang tepat adalah:',
   '["Frekuensi rendah (1 kHz) dengan bobbin probe","RFT pada frekuensi sangat rendah","Frekuensi rendah dengan encircling probe","Frekuensi tinggi (200 kHz-2 MHz) dengan surface/pencil probe"]', 3,
   'Frekuensi tinggi memberi skin depth dangkal dan resolusi tinggi untuk crack tepat di permukaan, dengan surface/pencil probe. RFT hanya untuk tube ferromagnetik, dan bobbin/encircling tidak sesuai untuk surface crack pada skin datar.', 'skin-crack', 'medium'),
  ('Cara membedakan sinyal lift-off (dari cat/primer) dari sinyal crack pada inspeksi skin adalah:',
   '["Berdasarkan phase angle — instrumen dirotasi agar lift-off horizontal dan crack vertikal","Berdasarkan amplitudo saja","Dengan menaikkan gain hingga keduanya hilang","Lift-off dan crack tidak dapat dibedakan dengan ET"]', 0,
   'Lift-off dan flaw terpisah berdasarkan phase angle di impedance plane. Instrumen dirotasi phase sehingga lift-off horizontal dan crack vertikal, memungkinkan operator membedakan keduanya meski permukaan bercat.', 'skin-crack', 'medium'),
  ('Conductivity meter ET untuk sorting alloy biasanya dikalibrasi dengan:',
   '["Satu reference standard tunggal","EDM notch pada bore fastener","Dua reference standard yang mengapit (bracketing) nilai target, mis. 30 dan 50 %IACS","Tanpa reference standard, langsung pada part"]', 2,
   'Conductivity sorting (dalam %IACS) dikalibrasi dengan dua standard bracketing agar pembacaan linear di rentang target. Ini berbeda dari kalibrasi crack detection yang memakai EDM notch.', 'conductivity', 'medium'),
  ('Pada 7075-T6 (acceptance band tipikal ~30.5-36 %IACS), pembacaan konduktivitas yang melewati batas atas menjadi ~38 %IACS paling mungkin mengindikasikan:',
   '["Heat damage / over-aging dengan kemungkinan kehilangan kekuatan","Material masih dalam kondisi normal","Crack permukaan yang besar","Lift-off akibat cat tebal"]', 0,
   'Overheat/over-aging pada aluminium menaikkan konduktivitas. Pembacaan yang melewati batas atas acceptance band mengindikasikan heat damage dan penurunan kekuatan; inspektor memetakan grid untuk menentukan batas zona heat-affected sebelum repair disposition. Crack dan lift-off tidak menaikkan reading konduktivitas absolut secara karakteristik seperti ini.', 'conductivity', 'hard'),
  ('Keunggulan utama eddy current array (ECA, ASTM E2884) untuk inspeksi skin/lap joint dibanding single coil manual adalah:',
   '["Tidak memerlukan kalibrasi","Hanya bekerja pada material ferromagnetik","Coverage lebar satu pass dengan C-scan imaging, mengurangi human factor","Menghilangkan kebutuhan akan phase rotation"]', 2,
   'Array memultipleks banyak coil untuk coverage lebar dalam satu pass dan menghasilkan C-scan image, mempercepat inspeksi area besar dan mengurangi human factor dibanding raster manual single coil. Kalibrasi dan phase rotation tetap diperlukan.', 'skin-crack', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 6 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;


-- ============================================================
-- SNS NDT — ET-L2 content (AUTO-GENERATED from authoring workflow)
-- Run AFTER seed_elearning_level2_all_methods.sql (modules must exist).
-- Steps: ON CONFLICT DO NOTHING (safe, never deletes user progress).
-- Quiz questions: DELETE+INSERT per quiz step (idempotent).
-- ============================================================

-- ET-L2 Module 7 (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Anatomi Written Procedure ET', '{"slides":[{"heading":"Kenapa Level II/III yang menulis prosedur","body":"Dalam hierarki ASNT/ISO 9712, penyusunan dan otorisasi written procedure ET adalah tanggung jawab Level III; Level II menjalankan, memverifikasi standardization, mengevaluasi, dan men-disposisi sesuai prosedur tersebut. Level I hanya menjalankan teknik yang sudah didefinisikan secara spesifik. Written procedure adalah dokumen terkendali (controlled document) yang menerjemahkan requirement dari referencing code/spec (mis. ASME Sec V Article 8, ASTM E309/E243) menjadi instruksi operasional yang repeatable: setiap operator qualified yang mengikutinya harus memperoleh hasil yang setara."},{"heading":"Essential vs non-essential variables","body":"ASME Sec V Article 8 (T-820) membedakan essential variable — parameter yang jika diubah di luar range tervalidasi WAJIB memicu requalification/technique demonstration ulang: frekuensi pemeriksaan, jenis/diameter/konfigurasi probe (abs vs diff, bobbin vs array), fill factor, scanning speed maksimum, kombinasi instrument/probe, panjang kabel maksimum, dan reference standard. Non-essential variable (mis. format laporan, identifikasi operator) boleh berubah tanpa requalification. Daftar essential variable harus eksplisit di dalam prosedur."},{"heading":"Isi minimum sebuah prosedur","body":"Scope & material yang dicakup; referencing code + acceptance spec; personnel qualification; equipment (model instrument, probe, panjang kabel maksimum); reference standard & artificial discontinuity (EDM notch, FBH, through-hole); kalibrasi/standardization & intervalnya; teknik scan (arah, overlap, kecepatan maksimum); data recording; evaluasi & acceptance criteria; pelaporan; serta revision control. Setiap item harus terukur (kuantitatif), bukan kualitatif."},{"heading":"Technique demonstration","body":"Prosedur ET tidak sah hanya di atas kertas — ASME Sec V menuntut technique demonstration: menjalankan prosedur pada reference standard / mock-up dengan flaw diketahui untuk membuktikan kemampuannya mendeteksi dan men-size target discontinuity. Hasil demonstrasi (signal amplitude, phase angle, signal-to-noise ratio) didokumentasikan sebagai baseline dan ditandatangani oleh Level III sebelum prosedur dirilis."}]}', 460, NULL),
  (2, 'reading', 'Reference Standard & Standardization', '{"slides":[{"heading":"Memilih reference standard","body":"Prosedur harus menetapkan reference standard yang material & kondisinya match dengan komponen: conductivity (%IACS) dan permeabilitas relatif (mu_r) setara, serta diameter dan wall thickness setara. Untuk tubing, ASTM E309 (bobbin tube dengan magnetic saturation) dan E243 (tube paduan tembaga) mengatur standar dengan through-drilled hole dan flat-bottom hole; untuk surface ET, EDM notch dengan kedalaman bertingkat. Mismatch material menggeser skin depth delta dan phase lag beta ~ x/delta, sehingga sizing menjadi salah."},{"heading":"Artificial discontinuity bertingkat","body":"Konvensi umum: through-hole, flat-bottom hole, dan/atau EDM notch pada 20%, 40%, 60%, dan 80% wall. Set bertingkat ini membentuk kurva kalibrasi phase-vs-depth untuk sizing % wall. Diameter through-hole standar ditetapkan oleh referencing spec dan dicantumkan eksplisit dalam prosedur — bukan dipilih operator di lapangan."},{"heading":"Standardization parameter","body":"Prosedur menetapkan: null/balance pada area bebas cacat; rotasi instrumen agar lift-off horizontal dan respons flaw vertikal pada impedance plane; set amplitude lubang referensi ke % FSH tertentu (mis. 50-80% layar); dan frekuensi inspeksi terhitung. Contoh anchor: probe pada Al, 40 %IACS, mu_r=1, frekuensi 100 kHz -> delta ~ 0.33 mm (21/sqrt(100 x 40 x 1)). Prosedur menuliskan angka frekuensi terhitung, bukan ''frekuensi sesuai operator''."},{"heading":"Interval & verifikasi standardization","body":"Tetapkan kapan re-standardization wajib: di awal, pada interval tetap (mis. tiap maksimum 4 jam atau tiap sejumlah tube), saat ganti operator/probe/instrument/baterai, dan di akhir. Bila verifikasi gagal (drift melebihi toleransi yang ditetapkan, mis. amplitude bergeser > batas % atau phase bergeser > beberapa derajat), semua data sejak standardization valid terakhir harus diinspeksi ulang. Aturan ini ditulis kuantitatif dalam prosedur."}]}', 480, NULL),
  (3, 'reading', 'Scan Plan, Multi-frequency & Acceptance', '{"slides":[{"heading":"Mendokumentasikan scan plan","body":"Prosedur menetapkan arah scan, coverage 100% dengan overlap minimum (mis. untuk array sesuai ASTM E2884), dan kecepatan scan maksimum sebagai essential variable — karena kecepatan berlebih menurunkan laju sampling dan dapat melewatkan cacat pendek. Untuk tubing bobbin: pull-speed maksimum (mis. tipikal 0.3-1 m/s tergantung instrumen) dan fill factor minimum ditetapkan agar sensitivitas konsisten."},{"heading":"Multi-frequency mixing dalam prosedur","body":"Bila support plate atau lift-off mengganggu, prosedur menetapkan mixing: kombinasi A - k*B(theta) yang di-cancel terhadap sinyal support plate/lift-off, sehingga sinyal cacat di bawah pelat penyangga terbaca. Prosedur mendefinisikan frekuensi tiap channel, urutan/pengaturan mixing, dan bukti demonstrasi bahwa mix menekan sinyal pelat penyangga sambil mempertahankan respons cacat referensi."},{"heading":"Acceptance criteria yang terukur","body":"Acceptance criteria TIDAK ditetapkan oleh standar metode NDT itu sendiri — ASME Sec V / ASTM mengatur TEKNIK. Threshold reject ditetapkan oleh referencing construction code / owner specification, mis. plug atau repair tube pada wall loss >= 40-50% (tergantung pemilik/aplikasi). Prosedur mengutip threshold ini secara eksplisit dengan basis pengukuran (phase-depth curve dari reference standard) sehingga evaluasi tidak subjektif."},{"heading":"Recording & reporting","body":"Tetapkan apa yang direkam (semua channel + mix, lokasi, amplitude, phase, % wall hasil sizing), media penyimpanan data mentah untuk audit, dan format laporan: identifikasi komponen, nomor prosedur + revisi, equipment, hasil per indikasi, disposisi (accept/reject/monitor), dan tanda tangan Level II. Data mentah disimpan agar evaluasi dapat diaudit ulang."}]}', 470, NULL),
  (4, 'reading', 'Kualifikasi Prosedur, Revisi & Audit', '{"slides":[{"heading":"Procedure qualification record","body":"Output dari technique demonstration didokumentasikan sebagai bukti kualifikasi: reference standard yang dipakai, parameter standardization, signal-to-noise ratio pada tiap artificial flaw, dan kesimpulan bahwa prosedur memenuhi requirement detection/sizing. Catatan ini disimpan dan dirujuk; ia membuktikan prosedur sah saat audit klien atau badan sertifikasi."},{"heading":"Revision control","body":"Setiap perubahan essential variable memicu revisi. Prosedur diberi nomor revisi & tanggal; revisi lama ditarik dari peredaran (obsolete) agar lapangan tidak memakai versi usang. Perubahan essential variable di luar range tervalidasi menuntut technique demonstration ulang sebelum rilis. Non-essential variable dapat direvisi dengan persetujuan tanpa demonstrasi ulang."},{"heading":"Kesalahan umum penyusunan","body":"Kriteria kualitatif (''scan perlahan'', ''frekuensi sesuai material'') yang tidak repeatable; lupa mencantumkan reference standard atau diameter through-hole; mencampuradukkan acceptance criteria dari standar metode NDT dengan owner spec; melewatkan technique demonstration; tidak mendaftar essential variable sehingga perubahan tak terkendali. Semua ini membuat prosedur gugur saat audit."},{"heading":"Sign-off & tanggung jawab","body":"Prosedur ET disusun dan diotorisasi oleh Level III (otorisasi metode), serta dijalankan dan diverifikasi oleh Level II. Level II bertanggung jawab memastikan standardization, evaluasi, dan disposisi sesuai prosedur. Tanda tangan adalah pernyataan teknis dan legal bahwa hasil inspeksi dapat dipertanggungjawabkan — bukan formalitas administratif."}]}', 430, NULL),
  (5, 'quiz', 'Mini-quiz — Procedure Development', '{"description":"7 soal: essential variable, reference standard, technique demonstration, acceptance criteria, multi-frequency, dan revision control dalam penyusunan written procedure ET Level II.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 7
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- ET-L2 Module 7 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'ET-L2' AND m."orderIndex" = 7 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'ET', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Dalam written procedure ET menurut ASME Sec V Article 8, apa yang dimaksud dengan essential variable?',
   '["Parameter administratif seperti nama operator dan format laporan","Parameter yang hanya relevan bagi operator Level I","Parameter yang jika diubah di luar range tervalidasi mewajibkan requalification prosedur","Parameter yang boleh diubah operator di lapangan tanpa pencatatan"]', 2,
   'Essential variable (mis. frekuensi, jenis/diameter probe, fill factor, scanning speed maksimum, reference standard) jika berubah di luar range tervalidasi mewajibkan requalification/technique demonstration ulang. Nama operator dan format laporan adalah non-essential.', 'Essential Variables', 'easy'),
  ('Mengapa technique demonstration diwajibkan sebelum sebuah written procedure ET dirilis?',
   '["Untuk membuktikan prosedur benar-benar mendeteksi dan men-size discontinuity target pada reference standard/mock-up","Untuk memenuhi syarat administratif tanpa perlu menjalankan probe","Untuk menggantikan kebutuhan reference standard saat inspeksi lapangan","Hanya untuk melatih Level I sebelum bekerja sendiri"]', 0,
   'Technique demonstration menjalankan prosedur pada reference standard/mock-up dengan flaw diketahui untuk membuktikan kemampuan deteksi & sizing; hasilnya (amplitude, phase, S/N) didokumentasikan sebagai baseline kualifikasi yang ditandatangani sebelum rilis.', 'Technique Demonstration', 'medium'),
  ('Pada penetapan reference standard untuk prosedur bobbin tubing, faktor mana yang paling kritis agar sizing % wall akurat?',
   '["Standard harus lebih panjang dari tube yang diinspeksi","Material standard match dalam conductivity (%IACS) dan permeabilitas (mu_r) dengan komponen","Standard cukup terbuat dari logam apa saja asalkan warnanya sama","Standard tidak perlu memiliki artificial discontinuity"]', 1,
   'Conductivity dan permeabilitas menentukan skin depth delta dan phase lag beta ~ x/delta. Bila material standard tidak match komponen, kurva phase-vs-depth bergeser sehingga sizing % wall salah. Standard juga harus memiliki artificial discontinuity bertingkat.', 'Reference Standard', 'medium'),
  ('Siapa yang menetapkan acceptance criteria (threshold reject) yang dikutip dalam written procedure ET?',
   '["ASME Sec V Article 8 yang menetapkan langsung batas % wall loss reject","Pabrikan instrumen eddy current","Operator Level I berdasarkan penilaian di lapangan","Referencing construction code / owner specification, bukan standar metode NDT itu sendiri"]', 3,
   'Standar metode NDT (ASME Sec V, ASTM) mengatur TEKNIK, bukan acceptance. Threshold seperti plug/repair pada wall loss >= 40-50% ditetapkan oleh referencing construction code / owner spec; prosedur mengutipnya eksplisit dengan basis phase-depth curve dari reference standard.', 'Acceptance Criteria', 'hard'),
  ('Konvensi umum artificial discontinuity bertingkat pada reference standard tubing untuk membentuk kurva phase-vs-depth adalah:',
   '["Hanya satu through-hole tunggal pada 50% wall","Through-hole/FBH/EDM notch pada 20%, 40%, 60%, dan 80% wall","Hanya notch permukaan tanpa lubang menembus dinding","Cacat acak tanpa kedalaman terukur"]', 1,
   'Set bertingkat 20/40/60/80% wall (kombinasi through-hole, flat-bottom hole, EDM notch) membentuk kurva kalibrasi phase-vs-depth untuk sizing. Diameter through-hole standar ditetapkan oleh referencing spec dan ditulis eksplisit dalam prosedur.', 'Reference Standard', 'medium'),
  ('Dalam prosedur multi-frequency untuk tubing dengan support plate, apa fungsi mixing channel A - k*B(theta)?',
   '["Menggandakan amplitude lift-off agar lebih mudah dilihat","Menghapus seluruh sinyal cacat agar layar bersih","Men-cancel sinyal support plate/lift-off sehingga sinyal cacat di bawahnya terbaca jelas","Menggantikan kebutuhan standardization pada reference standard"]', 2,
   'Mixing dua/tiga frekuensi (A - k*B(theta)) dikalibrasi untuk membatalkan sinyal support plate/lift-off sambil mempertahankan respons cacat. Prosedur mendefinisikan frekuensi tiap channel dan bukti demonstrasi bahwa mix menekan sinyal pelat penyangga.', 'Multi-frequency Technique', 'hard'),
  ('Apa konsekuensi prosedur dari mengubah scanning speed maksimum di luar range yang telah tervalidasi?',
   '["Tidak ada konsekuensi karena scanning speed bersifat non-essential","Memicu revisi dan technique demonstration ulang karena scanning speed adalah essential variable","Cukup dicatat di buku log tanpa merevisi prosedur","Otomatis disetujui oleh Level I tanpa keterlibatan Level II/III"]', 1,
   'Scanning speed maksimum adalah essential variable: kecepatan berlebih menurunkan laju sampling dan dapat melewatkan cacat pendek. Mengubahnya di luar range tervalidasi memicu revisi (nomor & tanggal baru) plus technique demonstration ulang sebelum rilis; revisi lama ditarik dari peredaran.', 'Revision Control', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 7 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- ET-L2 Module 8 (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'ASME V Article 8 — anatomi & ruang lingkup', '{"slides":[{"heading":"Apa yang diatur Article 8","body":"ASME Section V Article 8 mengatur Eddy Current Examination of Tubular Products (mis. tube heat exchanger / condenser). Article ini bersifat TECHNIQUE & CALIBRATION: ia menetapkan cara melakukan pemeriksaan (T-820 technique), peralatan, reference standard, dan kalibrasi — TETAPI tidak menetapkan kriteria penerimaan (acceptance). Kriteria acceptance datang dari referencing code/spec (mis. ASME Section VIII, B31.x, atau spesifikasi owner)."},{"heading":"Struktur paragraf T-8xx","body":"T-810 Scope; T-820 General (technique + variabel esensial); T-830 Equipment (instrument frekuensi tunggal/multi, probe absolute/differential, bobbin); T-840 Requirements (prosedur tertulis + demonstrasi); T-850 Technique (kalibrasi & scanning); T-860 Calibration (reference standard, sensitivitas, phase/frequency); T-870 Examination; T-880 Evaluation; T-890 Documentation/Report. Setiap paragraf ''T-'' bersifat mandatory bila Article 8 dirujuk."},{"heading":"Mandatory Appendices","body":"Mandatory Appendix I — Eddy Current Examination Method for Installed Nonferromagnetic Heat Exchanger Tubing (teknik bobbin). Article 8 juga memiliki appendix lain untuk variasi metode/aplikasi tube; selalu cek edisi Code untuk daftar appendix yang berlaku karena cakupannya berubah antar edisi. Appendix mendefinisikan reference standard (through-hole/flat-bottom hole/notch). Selalu identifikasi EDITION & ADDENDA Code yang dirujuk kontrak — variabel esensial dan format reference standard bisa berbeda antar edisi."},{"heading":"Pemisahan technique vs acceptance","body":"Kesalahan umum Level II: mengira Article 8 memberi angka batas reject. Tidak. Article 8 memastikan sinyal terukur konsisten & terkalibrasi. ANGKA penerimaan — misal plug/repair pada 40% atau 50% wall loss — ditetapkan owner/AIA melalui referencing construction/in-service code. Selalu sebut dua dokumen di prosedur: (1) Article 8 untuk technique, (2) referencing code untuk acceptance."}]}', 460, NULL),
  (2, 'reading', 'T-820/T-860 — variabel esensial & kalibrasi', '{"slides":[{"heading":"Essential vs nonessential variables","body":"T-820 mengharuskan prosedur tertulis dengan daftar variabel esensial: tipe & ukuran probe, frekuensi pemeriksaan, instrument/manufacturer, reference standard, scanning speed/direction, mode (absolute/differential), dan teknik analisis data. Perubahan variabel esensial = WAJIB requalification prosedur (revalidasi pada reference standard). Variabel nonesensial (mis. nama operator) tidak menuntut requalification."},{"heading":"Reference standard (T-860)","body":"Reference standard dibuat dari tube dengan material, diameter, dan wall thickness yang SAMA/nominal sama dengan tube yang diperiksa. Artificial discontinuity standar: through-drilled hole, flat-bottom hole, dan/atau circumferential/longitudinal groove. Contoh klasik bobbin: empat flat-bottom hole dan satu through-hole; atau notch EDM kedalaman 20/40/60/80% wall untuk depth sizing curve."},{"heading":"Set sensitivitas & phase","body":"Kalibrasi: null probe di tube bersih, lalu set respons dari through-hole / OD groove ke amplitudo & sudut fasa tertentu pada layar (mis. through-hole = full screen height). Orientasi instrument diatur agar lift-off horizontal (setelah null) dan sinyal flaw berputar fasa — sinyal cacat dibuat vertikal. Phase angle dari setiap notch kalibrasi membentuk depth curve (phase = kedalaman)."},{"heading":"Frekuensi & skin depth check","body":"Frekuensi dipilih agar fasa antara OD dan ID defect cukup terpisah. Gunakan delta praktis ~ 21/sqrt(f[kHz]*sigma[%IACS]*mu_r). Untuk Al 40 %IACS pada 100 kHz, mu_r=1, delta ~ 0,33 mm. Phase lag beta ~ x/delta rad: cacat lebih dalam memberi fasa lebih besar. Bila fasa OD vs ID terlalu rapat, turunkan frekuensi untuk memperbesar pemisahan fasa kedalaman."}]}', 480, NULL),
  (3, 'reading', 'ASTM E309 & E243 — tube standards', '{"slides":[{"heading":"ASTM E309 — bobbin + magnetic saturation","body":"ASTM E309 = Standard Practice for Eddy-Current Examination of Steel Tubular Products Using Magnetic Saturation. Untuk tube ferromagnetik/sebagian magnetik (mis. duplex, beberapa stainless, carbon steel tube), permeabilitas tinggi merusak sinyal ET. E309 menambahkan SATURATION COIL/magnet untuk menjenuhkan material (mu_r efektif mendekati 1) sehingga eddy current dapat menembus dan sinyal flaw kembali terbaca. Tanpa saturasi memadai, sinyal permeabilitas mendominasi noise."},{"heading":"Kapan E309 vs RFT","body":"E309 cocok bila saturasi penuh tercapai (dinding tipis, material dapat dijenuhkan). Bila tube terlalu tebal/ferromagnetik kuat sehingga saturasi tak tercapai, beralih ke RFT (remote field, through-transmission, ~full wall, phase=depth) atau IRIS (ultrasonik, akurat tapi lambat). Level II memilih metode berdasar feasibility saturasi & wall thickness, bukan kebiasaan."},{"heading":"ASTM E243 — Cu & Cu-alloy tube","body":"ASTM E243 = Standard Practice for Electromagnetic (Eddy-Current) Examination of Copper and Copper-Alloy Tubes. Banyak dipakai untuk tube condenser/heat exchanger admiralty brass, cupronickel (90/10, 70/30), Cu. Menetapkan reference standard (through-hole/notch), kecepatan, dan kalibrasi untuk material nonferromagnetik konduktif tinggi. Bedakan dari E309 yang untuk material yang butuh saturasi."},{"heading":"Memilih standar yang benar","body":"Aturan praktis: nonferromagnetik tembaga/kuningan -> E243; baja/feromagnetik dengan saturasi -> E309; tube terinstal HX nonferro umum -> ASME V Art 8 App I; array di tube -> E2884; bobbin tube generik -> E2096. Prosedur harus menyebut standar metode + referencing acceptance code. Salah standar = data tidak diterima auditor."}]}', 460, NULL),
  (4, 'reading', 'ASTM E2884 (array) & acceptance/plugging', '{"slides":[{"heading":"ASTM E2884 — array eddy current","body":"ASTM E2884 = Standard Guide for Eddy Current Testing of Electrically Conducting Materials Using Conformable Sensor Arrays. Mengatur probe array (banyak coil) untuk surface/near-surface scanning dengan C-scan imaging, coverage lebar tanpa banyak pass, dan deteksi crack berorientasi acak. Variabel: konfigurasi elemen, drive-receive, encoder, kalibrasi tiap channel, dan reference standard dengan EDM notch. Bedakan dari E2096 (general bobbin tube)."},{"heading":"Sizing & depth curve","body":"Kedalaman cacat dibaca dari PHASE ANGLE (bukan amplitudo) pada bobbin/RFT, dikalibrasi via notch 20/40/60/80% wall membentuk kurva fasa-vs-depth. Through-wall hole = referensi 100% amplitudo. Amplitudo dipengaruhi volume & lift-off, jadi untuk depth gunakan fasa; untuk klasifikasi OD/ID gunakan arah/fasa relatif lift-off horizontal."},{"heading":"Acceptance = referencing code","body":"Article 8/E243/E309/E2884 TIDAK memberi angka reject. Acceptance ditetapkan owner/referencing code via % wall loss. Praktik HX umum: indikasi diukur sebagai % wall loss; plugging/repair pada ambang owner — sering 40% atau 50% wall loss (atau lebih konservatif untuk tube kritis). Through-wall (leak) = plug segera. Selalu kutip dokumen acceptance & ambang persisnya di laporan."},{"heading":"Evaluasi & dokumentasi (T-880/T-890)","body":"Setiap indikasi >= ambang reporting (mis. >20% wall) dicatat: nomor tube (peta tube-sheet), lokasi aksial (dari support plate/inlet), % wall loss, fasa, dan tipe (OD/ID/support/dent/pluggable). Laporan menyebut prosedur, edition Code, reference standard ID, kalibrasi awal/akhir (drift check), instrument, dan operator bersertifikat. Verifikasi: re-test setelah re-plug/repair untuk konfirmasi integritas."}]}', 480, NULL),
  (5, 'quiz', 'Mini-quiz — Advanced Code Interpretation', '{"description":"7 soal interpretasi kode lanjutan: ASME V Article 8 (technique vs acceptance, variabel esensial, reference standard, dokumentasi), ASTM E309/E243/E2884, sizing fasa, dan kriteria plugging % wall loss.","questionCount":7,"passingScore":75}', 680, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 8
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- ET-L2 Module 8 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'ET-L2' AND m."orderIndex" = 8 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'ET', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Dalam ASME Section V Article 8, dari mana kriteria penerimaan (acceptance) seperti ambang plugging % wall loss sebenarnya berasal?',
   '["Dari paragraf T-880 Evaluation di dalam Article 8 itu sendiri","Dari referencing code/spesifikasi (mis. construction code atau spesifikasi owner), bukan dari Article 8","Dari reference standard yang dibuat saat kalibrasi","Dari rekomendasi pabrik pembuat instrument eddy current"]', 1,
   'Article 8 bersifat technique & calibration: ia mengatur cara pemeriksaan, peralatan, reference standard, dan kalibrasi, tetapi TIDAK menetapkan angka acceptance. Kriteria penerimaan (mis. plug pada 40-50% wall loss) ditetapkan oleh referencing code/spec atau owner. Prosedur harus menyebut dua dokumen: Article 8 untuk technique dan referencing code untuk acceptance.', 'ASME V Article 8', 'medium'),
  ('Sebuah prosedur ET tube terkualifikasi memakai probe bobbin pada 100 kHz. Operator ingin mengganti frekuensi menjadi 35 kHz untuk memperbesar pemisahan fasa kedalaman. Menurut T-820, apa konsekuensinya?',
   '["Tidak ada konsekuensi karena frekuensi adalah variabel nonesensial","Cukup dicatat di logbook tanpa tindakan lain","Frekuensi adalah variabel esensial, sehingga prosedur wajib direkualifikasi (revalidasi pada reference standard)","Hanya perlu persetujuan lisan dari operator Level III tanpa requalification"]', 2,
   'Frekuensi pemeriksaan termasuk variabel esensial dalam T-820. Mengubah variabel esensial (frekuensi, ukuran/tipe probe, instrument, reference standard, mode absolute/differential, dll.) menuntut requalification prosedur dengan revalidasi pada reference standard. Variabel nonesensial seperti nama operator tidak menuntut requalification.', 'ASME V Article 8', 'medium'),
  ('Mengapa ASTM E309 menambahkan magnetic saturation coil saat memeriksa steel tubular products dengan eddy current?',
   '["Untuk meningkatkan kecepatan scanning probe di dalam tube","Untuk menjenuhkan material sehingga permeabilitas efektif mendekati 1, memungkinkan eddy current menembus dan sinyal flaw terbaca","Untuk mendinginkan probe agar tidak overheat pada tube panas","Untuk menaikkan amplitudo lift-off agar mudah dikalibrasi"]', 1,
   'Pada material ferromagnetik, permeabilitas tinggi mendominasi dan merusak sinyal ET. ASTM E309 (Eddy-Current Examination of Steel Tubular Products Using Magnetic Saturation) menambahkan saturation coil/magnet untuk menjenuhkan material sehingga mu_r efektif mendekati 1; dengan demikian eddy current dapat menembus dinding dan sinyal flaw kembali terbaca, bukan tenggelam dalam noise permeabilitas.', 'ASTM E309', 'medium'),
  ('Untuk tube condenser dari cupronickel 90/10 (nonferromagnetik, konduktif), standar ASTM praktik mana yang paling tepat dirujuk untuk eddy current examination-nya?',
   '["ASTM E309 (steel tubular products dengan magnetic saturation)","ASTM E243 (electromagnetic/eddy-current examination of copper and copper-alloy tubes)","ASTM E2884 (conformable sensor arrays untuk surface scanning)","ASTM E1444 (magnetic particle testing)"]', 1,
   'ASTM E243 adalah Standard Practice for Electromagnetic (Eddy-Current) Examination of Copper and Copper-Alloy Tubes, dipakai untuk tube condenser/HX seperti admiralty brass dan cupronickel 90/10 atau 70/30. E309 untuk baja yang butuh saturasi; E2884 untuk array sensor surface; E1444 adalah MT, bukan ET.', 'ASTM E243', 'easy'),
  ('Pada kalibrasi bobbin dengan reference standard bertakik EDM 20/40/60/80% wall, parameter apa yang paling tepat digunakan untuk menentukan KEDALAMAN (sizing) suatu cacat?',
   '["Phase angle indikasi, yang dikalibrasi menjadi kurva fasa-vs-depth dari notch referensi","Amplitudo sinyal, karena selalu proporsional dengan kedalaman","Kecepatan scanning probe saat melewati cacat","Warna sinyal pada layar impedance plane"]', 0,
   'Kedalaman dibaca dari phase angle, bukan amplitudo. Phase lag beta ~ x/delta: cacat lebih dalam memberi fasa lebih besar. Notch 20/40/60/80% wall membentuk kurva fasa-vs-depth, dengan through-wall hole sebagai referensi amplitudo. Amplitudo dipengaruhi volume cacat dan lift-off sehingga tidak andal untuk sizing kedalaman; fasa jauh lebih stabil untuk depth.', 'Kalibrasi & sizing', 'medium'),
  ('ASTM E2884 paling tepat menjadi acuan untuk teknik eddy current jenis apa?',
   '["Bobbin probe absolute untuk corrosion mapping di dalam tube heat exchanger","Remote field technique pada tube ferromagnetik tebal","Conformable sensor array (banyak coil) untuk surface/near-surface scanning dengan C-scan imaging","Internal Rotary Inspection System berbasis ultrasonik"]', 2,
   'ASTM E2884 adalah Standard Guide for Eddy Current Testing Using Conformable Sensor Arrays: probe array multi-elemen untuk surface/near-surface scanning, coverage lebar tanpa banyak pass, C-scan imaging, dan deteksi crack berorientasi acak. RFT dan IRIS adalah metode tube terpisah; bobbin tube generik diatur antara lain oleh E2096/Article 8 App I, bukan E2884.', 'ASTM E2884', 'medium'),
  ('Sebuah tube HX nonferromagnetik berdinding 1,2 mm akan diperiksa dengan bobbin. Saat memilih frekuensi, hubungan fasa OD-vs-ID terlalu rapat sehingga OD dan ID sulit dibedakan. Tindakan teknis yang paling tepat menurut prinsip skin depth/phase lag adalah:',
   '["Menaikkan frekuensi agar amplitudo cacat ID membesar","Menurunkan frekuensi sehingga delta lebih besar relatif terhadap dinding dan pemisahan fasa OD-ID melebar","Mengganti probe bobbin menjadi probe surface tunggal","Menambah saturation coil agar fasa OD-ID terpisah"]', 1,
   'Pemisahan fasa antara cacat OD dan ID bergantung pada phase lag yang berkembang sepanjang dinding (beta ~ x/delta). Menurunkan frekuensi memperbesar delta praktis (delta ~ 21/sqrt(f*sigma*mu_r)), sehingga distribusi fasa antara permukaan dalam dan luar menjadi lebih lebar dan OD/ID lebih mudah dibedakan. Menaikkan frekuensi justru merapatkan fasa OD-ID; saturation coil hanya relevan untuk material ferromagnetik, bukan untuk memisahkan fasa OD-ID pada tube nonferro.', 'Skin depth & frekuensi', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 8 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- ET-L2 Module 9 (6 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Case 1 — Heat exchanger tube, OD pitting corrosion (bobbin dual-frequency)', '{"slides":[{"heading":"Komponen & setup","body":"Tube admiralty brass (sigma ~26 %IACS, mu_r=1), OD 19 mm, wall nominal 1.65 mm, panjang 6 m, susunan triangular pitch dengan 7 support plate. Probe bobbin differential + absolute, dual-frequency: f-primary 35 kHz (sensitif OD defect), f-aux 13 kHz (referensi support plate untuk mixing). Kalibrasi pada ASME Sec. V Article 8 reference standard dengan through-hole + flat-bottom hole (FBH) pada 20/40/60/80 % wall. Differential channel unggul untuk pit terlokalisasi; absolute channel untuk thinning bertahap & baseline."},{"heading":"Sinyal impedance plane","body":"Setelah null & rotasi: lift-off dibuat horizontal. Pada posisi 2.1 m dari inlet, differential channel menampilkan sinyal Lissajous figure-of-eight dengan phase angle ~95 derajat (referensi standar: 40 % FBH = ~110 derajat, 60 % FBH = ~85 derajat). Mix channel (A - k*B, k disetel agar sinyal support plate nol) menghapus support-plate signal periodik sehingga indikasi defect berdiri sendiri, tidak overlap dengan support plate edge."},{"heading":"Klasifikasi & sizing","body":"Phase ~95 derajat berada di antara node 40 % (110 deg) dan 60 % (85 deg). Interpolasi linear phase-vs-depth: (110-95)/(110-85) = 0.6 -> ~52 % wall loss OD. Pola differential simetris dengan amplitudo terlokalisasi = pitting (bukan general thinning, yang menghasilkan sinyal melebar/landai pada absolute channel). Absolute channel mengkonfirmasi volume terbatas (single pit cluster), konsisten dengan OD pitting corrosion akibat cooling water."},{"heading":"Keputusan & dokumentasi","body":"Acceptance ditetapkan oleh referencing spec, bukan oleh sinyal ET semata. Owner/TEMA spec plant: plug pada >= 50 % wall loss untuk admiralty brass cooling water. 52 % > 50 % -> PLUG tube. Tube ditandai pada tubesheet map (row/column), di-plug kedua ujung, dan dicatat di laporan: lokasi axial, phase angle, % wall, channel/mix setting, serta reference standard (ASME Sec. V Art. 8) yang dipakai."}]}', 470, NULL),
  (2, 'reading', 'Case 2 — Ferromagnetic boiler tube wall loss (RFT + IRIS cross-check)', '{"slides":[{"heading":"Mengapa bobbin gagal di sini","body":"Tube carbon steel feedwater heater bersifat ferromagnetik (mu_r tinggi, ratusan-ribuan). Skin depth delta = 1/sqrt(pi*f*mu*sigma); karena mu sangat besar, delta menjadi sangat tipis sehingga conventional bobbin ET tidak menembus dinding. Solusi: Remote Field Testing (RFT, through-transmission) sesuai ASTM E2096; sensitif ~full wall thickness dan kira-kira equally sensitif untuk defect ID maupun OD."},{"heading":"Setup & kalibrasi","body":"Probe RFT exciter-receiver dengan spacing ~2-3x diameter tube (zona remote field). Kalibrasi pada reference tube dengan groove/flat-bottom hole bertingkat (mis. 20/40/60/80 % wall). Dalam RFT, phase lag (bukan amplitudo) adalah parameter utama: kedalaman defect kira-kira proporsional terhadap pergeseran phase, dan konsisten untuk ID maupun OD karena sifat double-through-wall transmission."},{"heading":"Sinyal & sizing","body":"Pada 3.4 m, voltage-plane menunjukkan phase shift yang dipetakan ke kurva kalibrasi -> ~68 % wall loss. Karakter sinyal: gradual, lebar axial ~25 mm = general/grooving corrosion (bukan pit tajam). RFT kurang andal membedakan ID vs OD dan sizing pit kecil; karena itu dilakukan IRIS spot-check (ultrasonic, akurat) -> wall tersisa 0.9 mm dari nominal 2.8 mm => (2.8-0.9)/2.8 = 68 %, cocok dengan RFT."},{"heading":"Keputusan & verifikasi silang","body":"Threshold repair owner: plug pada >= 60 % wall loss. 68 % -> melebihi -> PLUG (tube tidak praktis di-weld repair internal). Verifikasi silang RFT vs IRIS mengkonfirmasi sizing sebelum keputusan final; combined-method validation seperti ini adalah praktik Level II yang baik ketika satu metode punya keterbatasan inheren."}]}', 480, NULL),
  (3, 'reading', 'Case 3 — Fastener hole fatigue crack (rotating / array probe)', '{"slides":[{"heading":"Skenario aerospace","body":"Wing skin aluminium 7075-T6 (sigma ~33 %IACS, mu_r=1), fastener hole diameter 6.35 mm, dilakukan saat overhaul setelah cat & fastener dilepas. Tugas: deteksi fatigue corner crack pada tepi/dinding lubang. Probe rotating ET (eddy current rotating scanner) atau eddy current array (ASTM E2884) untuk imaging 360 derajat dinding lubang dengan resolusi posisi sudut."},{"heading":"Frekuensi & skin depth","body":"Untuk Al 33 %IACS gunakan delta[mm] ~ 21/sqrt(f[kHz]*sigma*mu_r). Pada 200 kHz: delta ~ 21/sqrt(200*33*1) = 21/81.2 ~ 0.26 mm -> dangkal, cocok untuk surface/near-surface crack di dinding lubang. Frekuensi tinggi dipilih agar sinyal crack tajam, resolusi tinggi, dan lift-off mudah dipisahkan secara phase dari sinyal crack."},{"heading":"Sinyal & klasifikasi","body":"C-scan array menampilkan indikasi pada posisi jam-3 dekat far-faying surface: sinyal crack berorientasi phase ~vertikal (instrumen sudah dirotasi: lift-off horizontal, flaw vertikal). Amplitudo melebihi level dari EDM notch referensi (kalibrasi pada ring/hole standard dengan EDM notch, mis. 0.5 mm & 1.0 mm). Pola tajam & terlokalisasi = crack, bukan korosi (gradual) atau lift-off/probe wobble (horizontal)."},{"heading":"Keputusan","body":"Maintenance manual / SRM: setiap crack-like indication terkonfirmasi pada fastener hole struktur primer = REJECT (zero-tolerance untuk fatigue crack). Disposition engineering: oversize/ream hole untuk membuang crack lalu re-inspect, atau ganti komponen. Berbeda dari tube (PLUG) -> di sini repair/replace. Acceptance ditentukan oleh referencing spec, bukan oleh ET signal sendiri."}]}', 480, NULL),
  (4, 'reading', 'Case 4 — Conductivity sorting & lift-off pitfall', '{"slides":[{"heading":"Skenario sorting","body":"Batch bracket aluminium dicurigai heat-treat error (temper salah). ET conductivity meter (frekuensi tetap, mis. 60 kHz) dipakai untuk sorting %IACS sebagai proxy temper/hardness. Spec: 7075-T6 ~30-35 %IACS; pembacaan jauh lebih tinggi (mis. 38-40 %IACS) mengindikasikan over-aged/temper salah karena over-aging menaikkan konduktivitas -> reject."},{"heading":"Sumber error: lift-off","body":"Cat/coating menambah lift-off yang menggeser pembacaan conductivity (umumnya membuat reading lebih rendah dari nilai sebenarnya). Pada impedance plane, lift-off bergerak sepanjang sumbu horizontal (setelah null). Conductivity meter harus dikalibrasi pada certified conductivity reference block, dan lift-off compensation diverifikasi dengan shim non-konduktif (mis. 0.1 mm) sebelum sorting."},{"heading":"Hasil & klasifikasi","body":"Setelah coating dikupas pada area uji dan instrumen dikalibrasi: 12 part terbaca 31-34 %IACS (PASS, dalam spec), 3 part terbaca ~39 %IACS (FAIL, di atas spec). Re-test dengan lift-off shim mengkonfirmasi pembacaan FAIL bukan artefak coating -> material benar-benar over-aged (konduktivitas naik)."},{"heading":"Keputusan","body":"3 part FAIL -> reject/quarantine, escalate ke metallurgy untuk konfirmasi hardness/temper. Pelajaran Level II: jangan menerima reading conductivity tanpa verifikasi lift-off & permukaan; selalu dokumentasikan certified reference block, koreksi temperatur (conductivity sangat sensitif suhu), dan kondisi permukaan."}]}', 440, NULL),
  (5, 'reading', 'Case 5 — Repair verification & dispositioning (ground weld toe)', '{"slides":[{"heading":"Konteks verifikasi pasca-repair","body":"Setelah grinding untuk membuang surface crack pada weld toe (carbon steel ferromagnetik), perlu verifikasi crack benar-benar hilang. ET surface probe absolute dipakai pada area ground. Pada material ferromagnetik gunakan probe ber-magnetic saturation atau probe khusus; ET sering dikombinasi dengan MT/PT untuk konfirmasi karena ET di ferromagnetik rawan noise permeabilitas."},{"heading":"Baseline & re-scan","body":"Sebelum grinding: indikasi crack phase tajam, amplitudo ~80 % FSH (kalibrasi pada EDM notch). Setelah grinding ~0.8 mm: re-scan menunjukkan amplitudo turun ke ~10 % FSH (background lift-off/edge effect), tanpa sinyal crack-like vertikal. Bandingkan terhadap noise floor referensi pada blend area, bukan hanya angka absolut."},{"heading":"Kriteria penerimaan repair","body":"Acceptance per referencing code/spec: crack fully removed (tidak ada indikasi di atas recording level) DAN ketebalan sisa setelah grinding tetap di atas minimum design wall (dikonfirmasi UT thickness). Blend grinding harus smooth (rasio mis. 4:1) agar tidak menjadi stress riser/notch baru yang memicu retak ulang."},{"heading":"Disposition & dokumentasi","body":"Hasil: crack removed, wall sisa 11.2 mm > minimum design 10.0 mm -> ACCEPT repair. Dokumentasi wajib: lokasi, before/after signal, reference standard, depth ground, wall sisa (UT), metode konfirmasi (ET + MT). Level II menandatangani disposition; traceability penuh adalah inti audit ASME / ISO 9712."}]}', 460, NULL),
  (6, 'quiz', 'Mini-quiz — Field case studies & disposition', '{"description":"7 soal studi kasus lapangan: pemilihan metode, klasifikasi sinyal, sizing % wall, dan keputusan plug/repair/verify. Acceptance selalu mengacu ke referencing code/spec.","questionCount":7,"passingScore":75}', 690, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 9
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- ET-L2 Module 9 mini-quiz (7 questions, step 6)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'ET-L2' AND m."orderIndex" = 9 AND ls."orderIndex" = 6 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'ET', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada Case 1 (tube admiralty brass), differential channel menampilkan phase ~95 derajat; standar kalibrasi memberi 40 % FBH = 110 derajat dan 60 % FBH = 85 derajat. Dengan interpolasi linear phase-vs-depth, berapa % wall loss dan apa keputusannya jika owner men-plug pada >= 50 %?',
   '["~30 % wall loss -> biarkan & monitor","~52 % wall loss -> PLUG tube","~75 % wall loss -> weld repair internal","~40 % wall loss -> tidak ada tindakan"]', 1,
   'Interpolasi: (110-95)/(110-85) = 15/25 = 0.6 -> 40 + 0.6x20 = ~52 % wall. Karena 52 % melebihi threshold plug 50 %, tube di-plug. Tube tidak di-weld repair internal (tidak praktis untuk tube HX), dan 30/40/75 % tidak konsisten dengan interpolasi.', 'Sizing & disposition', 'hard'),
  ('Mengapa conventional bobbin ET gagal pada tube carbon steel ferromagnetik (Case 2) sehingga RFT dipilih?',
   '["Carbon steel terlalu konduktif sehingga sinyal selalu jenuh","Bobbin probe secara fisik tidak muat ke dalam tube ferromagnetik","Permeabilitas (mu_r) tinggi membuat skin depth sangat tipis sehingga medan tidak menembus dinding","RFT lebih cepat di-scan dibanding bobbin sehingga selalu dipilih"]', 2,
   'delta = 1/sqrt(pi*f*mu*sigma); mu_r tinggi pada ferromagnetik membuat skin depth sangat kecil, jadi conventional bobbin tidak menembus full wall. RFT (through-transmission) sensitif ~full wall untuk ID maupun OD. RFT justru lebih lambat, bukan lebih cepat, dan masalahnya bukan ukuran fisik probe maupun saturasi konduktivitas.', 'Method selection', 'medium'),
  ('Dalam RFT (Case 2), parameter utama untuk menentukan kedalaman defect adalah:',
   '["Phase lag yang dipetakan ke kurva kalibrasi reference tube","Amplitudo absolut sinyal saja","Frekuensi resonansi probe","Skema warna pada tampilan C-scan"]', 0,
   'Pada RFT, phase lag kira-kira proporsional terhadap kedalaman defect dan konsisten untuk ID/OD karena double-through-wall transmission; phase (bukan amplitudo) adalah indikator depth utama yang dipetakan ke kurva kalibrasi. Amplitudo dipakai untuk deteksi tetapi bukan pengukur depth utama.', 'RFT interpretation', 'medium'),
  ('Pada Case 3, fastener hole Al 7075 (sigma ~33 %IACS, mu_r=1) diinspeksi pada 200 kHz. Dengan delta[mm] ~ 21/sqrt(f[kHz]*sigma*mu_r), berapa perkiraan skin depth?',
   '["~2.6 mm","~1.3 mm","~0.03 mm","~0.26 mm"]', 3,
   'delta ~ 21/sqrt(200x33x1) = 21/sqrt(6600) = 21/81.2 ~ 0.26 mm. Skin depth dangkal ini cocok untuk corner/surface crack di dinding lubang dengan sinyal tajam. Nilai 2.6/1.3/0.03 mm muncul dari salah pangkat/salah satuan.', 'Skin depth calculation', 'hard'),
  ('Setelah instrumen dirotasi dengan benar pada inspeksi fastener hole (Case 3), bagaimana sinyal crack vs lift-off muncul di impedance plane?',
   '["Crack selalu tepat 45 derajat terhadap lift-off","Lift-off horizontal, sinyal crack berorientasi vertikal","Lift-off vertikal, crack horizontal","Keduanya horizontal sehingga tidak bisa dipisahkan"]', 1,
   'Konvensi: setelah null & rotasi, lift-off dibuat horizontal sehingga flaw (crack) berdiri vertikal, memudahkan diskriminasi crack dari variasi lift-off/probe wobble. Inilah dasar pemisahan sinyal pada impedance plane.', 'Impedance plane', 'easy'),
  ('Pada Case 4, conductivity sorting Al 7075-T6 (spec ~30-35 %IACS) membaca ~39 %IACS pada 3 part yang bercoating. Langkah verifikasi paling tepat SEBELUM menyatakan reject adalah:',
   '["Langsung reject karena angka di atas 35 %IACS","Naikkan frekuensi sampai pembacaan masuk spec","Kupas coating di area uji, kalibrasi ulang pada certified reference block, dan verifikasi lift-off dengan shim","Abaikan karena coating selalu menaikkan pembacaan conductivity"]', 2,
   'Lift-off dari coating menggeser pembacaan conductivity, jadi Level II harus memverifikasi dulu: kupas coating, kalibrasi pada certified reference block, dan cek lift-off compensation dengan shim. Setelah verifikasi, ~39 %IACS terkonfirmasi over-aged -> reject ke metallurgy. Coating umumnya menurunkan (bukan menaikkan) pembacaan, dan menaikkan frekuensi tidak mengubah konduktivitas material.', 'Conductivity sorting', 'medium'),
  ('Pada Case 5 (verifikasi repair weld toe ferromagnetik), kriteria utama untuk ACCEPT repair setelah grinding adalah:',
   '["Amplitudo sinyal naik dibanding baseline sebelum grinding","Grinding minimal 2 mm tanpa perlu cek ketebalan sisa","Tidak ada indikasi crack-like di atas recording level DAN wall sisa masih di atas minimum design wall","Blend grinding dibuat tajam agar setiap crack mudah terlihat"]', 2,
   'Repair diterima bila crack benar-benar dihilangkan (tidak ada indikasi di atas recording level) dan wall sisa setelah grinding tetap di atas minimum design wall (dikonfirmasi UT). Blend harus smooth (mis. 4:1) agar tidak menjadi stress riser baru; amplitudo seharusnya turun (crack hilang), bukan naik.', 'Repair verification', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 9 AND ls."orderIndex" = 6 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- ET-L2 Module 10 — Recap & Practice Exam (4 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Recap I — Fisika ET & Impedance Plane', '{"slides":[{"heading":"Skin depth & phase lag","body":"Skin depth standar delta = 1/sqrt(pi*f*mu*sigma). Rumus praktis delta[mm] ~ 21/sqrt(f[kHz]*sigma[%IACS]*mu_r). Anchor: Al 100 kHz, 40 %IACS, mu_r=1 -> delta ~ 0.33 mm. Karena delta berbanding terbalik dengan sqrt(f), menaikkan frekuensi 4x (100->400 kHz) menurunkan delta menjadi setengahnya (~0.17 mm) sehingga lebih sensitif terhadap defect dangkal / dekat permukaan probe. Phase lag beta ~ x/delta rad: indikasi lebih dalam menghasilkan rotasi fasa lebih besar — dasar utama estimasi kedalaman/sizing."},{"heading":"Impedance plane fundamentals","body":"Setelah null, lift-off membentuk garis yang dibuat horizontal melalui rotasi display; sinyal flaw memutar fasa relatif terhadap lift-off (mendekati vertikal) sehingga mudah didiskriminasi. Conductivity & frekuensi menggeser titik operasi sepanjang impedance/conductivity curve; kenaikan permeabilitas (material ferromagnetic) menaikkan komponen induktif (reaktansi) secara tajam dan mendorong operasi ke knee point."},{"heading":"Conductivity sorting","body":"Sorting %IACS memakai frekuensi tetap dan dikalibrasi pada conductivity reference block bersertifikat; pergeseran fasa/amplitudo membedakan paduan, temper, atau heat damage. Lift-off wajib dikompensasi (biasanya dengan plastik shim tipis pada kalibrasi) agar tidak salah baca conductivity. Aplikasi tipikal: verifikasi alloy/temper aerospace dan deteksi over-temperature (heat damage) pada paduan aluminium."}]}', 460, NULL),
  (2, 'reading', 'Recap II — Multi-frekuensi, Probe & Metode Alternatif', '{"slides":[{"heading":"Multi-frequency mixing","body":"Mixing A - k*B(theta) membatalkan sinyal support plate / lift-off: channel A sensitif defect, channel B referensi gangguan, gain k & rotasi theta diatur sehingga sinyal gangguan menjadi nol pada hasil mix. Heat exchanger dengan banyak tube support plate (TSP) umumnya butuh three-frequency mixing untuk membersihkan sinyal di bawah TSP sambil mempertahankan sensitivitas defect. Frekuensi prime dipilih agar phase angle TSP dan defect cukup terpisah."},{"heading":"Probe selection","body":"Surface (weld/aerospace skin), bobbin absolute/differential (tube non-ferromagnetic dari ID), encircling (bar/tube/wire dari luar), array sesuai ASTM E2884 (coverage lebar, C-scan imaging, tanpa rotasi mekanik), rotating untuk fastener-hole. Differential menonjolkan defect lokal pendek & menekan drift termal serta gradual variation; absolute lebih baik membaca gradual / long wall loss dan dapat mengukur properti absolut."},{"heading":"Metode alternatif: RFT / IRIS / MFL","body":"RFT: tube ferromagnetic, melalui prinsip through-transmission (through-wall), penetrasi mendekati full wall, sizing berbasis phase = depth, sensitivitas ID dan OD hampir sama (sulit membedakan ID/OD). IRIS: ultrasonic dengan rotating mirror, pengukuran ketebalan dinding sangat akurat & kuantitatif tetapi lambat dan butuh water coupling serta tube bersih. MFL: cepat untuk material ferromagnetic, baik untuk metal loss volumetrik/pitting (mis. pipeline pig), namun sizing kuantitatif terbatas."}]}', 480, NULL),
  (3, 'reading', 'Recap III — Code, Prosedur, Aerospace & Case Studies', '{"slides":[{"heading":"Codes & standards","body":"ASME Section V Article 8: eddy current examination — T-820 technique, reference standard & kalibrasi tube ET. ASTM E309 (bobbin tube dengan magnetic saturation), E243 (seamless Cu & Cu-alloy tube), E2884 (eddy current array), E2096; ISO 15548 (equipment characteristics) & ISO 15549 (general principles). Kriteria acceptance TIDAK ditetapkan oleh operator, melainkan oleh referencing code/spec/owner (mis. plug/repair pada 40-50% wall loss tergantung pemilik)."},{"heading":"Kalibrasi & reference standard","body":"Kalibrasi pada reference standard dengan artificial discontinuity: EDM notch / flat-bottom hole / through-hole pada kedalaman bertingkat (mis. 20/40/60/80% wall). Bangun kurva fasa-vs-kedalaman pada standar lalu interpolasi indikasi lapangan untuk sizing. Verifikasi sistem (system check) sebelum & sesudah scan; periksa drift, fill factor, sensitivitas, dan kecepatan tarik probe agar dalam toleransi prosedur."},{"heading":"Procedure development","body":"Prosedur Level II menetapkan: scope/material & dimensi, peralatan & probe, frekuensi (termasuk mix), reference standard, teknik null & rotasi display, scanning speed, recording/recording threshold, kriteria evaluasi (sizing), dan acceptance dari referencing code. Kualifikasi/demonstrasi prosedur dilakukan pada reference standard sebelum produksi; Level II dapat menulis & mengkualifikasi teknik dalam batas yang disetujui Level III."},{"heading":"Aerospace & case studies","body":"Aerospace: rotating probe untuk fastener-hole crack, surface array untuk fuselage/lap-joint skin crack, conductivity sorting untuk heat damage/verifikasi temper. Case study tube: indikasi ~60% wall di bawah TSP -> three-freq mix untuk konfirmasi & sizing -> tindak lanjut plug (umumnya melebihi ambang). Feedwater heater ferromagnetic -> RFT, indikasi groove/erosion. Selalu bedakan defect sejati dari sinyal geometry (dent, support plate, baffle, tube end) sebelum sizing."}]}', 500, NULL),
  (4, 'quiz', 'Practice Exam — ET Level II (25 soal)', '{"description":"Ujian latihan komprehensif ET Level II mencakup modul 1-9: fisika ET, impedance plane, multi-frekuensi, probe, RFT/IRIS/MFL, code & standar, kalibrasi, prosedur, aerospace, dan case studies. 25 soal, minimal 75%.","questionCount":25,"passingScore":75}', 720, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 10
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- ET-L2 Module 10 mini-quiz (25 questions, step 4)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'ET-L2' AND m."orderIndex" = 10 AND ls."orderIndex" = 4 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'ET', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Untuk Al 40 %IACS, mu_r=1, pada 100 kHz, skin depth (delta) praktis paling mendekati nilai mana?',
   '["0.33 mm","0.033 mm","3.3 mm","33 mm"]', 0,
   'delta ~ 21/sqrt(f*sigma*mu_r) = 21/sqrt(100*40*1) = 21/sqrt(4000) ~ 21/63.2 ~ 0.33 mm.', 'Fisika ET', 'medium'),
  ('Jika frekuensi inspeksi dinaikkan dari 100 kHz ke 400 kHz pada material yang sama, skin depth akan menjadi sekitar:',
   '["2x lebih besar","4x lebih besar","Setengahnya","Tidak berubah"]', 2,
   'delta berbanding terbalik dengan sqrt(f). Frekuensi naik 4x -> delta turun faktor sqrt(4)=2, jadi menjadi setengahnya (~0.17 mm dari ~0.33 mm).', 'Fisika ET', 'medium'),
  ('Phase lag (beta) untuk defect pada kedalaman x dari permukaan paling tepat diperkirakan dengan:',
   '["beta ~ delta/x rad","beta ~ x/delta rad","beta ~ x*delta rad","beta ~ x^2/delta rad"]', 1,
   'Phase lag bertambah kira-kira linear terhadap kedalaman relatif terhadap skin depth: beta ~ x/delta rad. Inilah dasar estimasi kedalaman dari rotasi fasa.', 'Fisika ET', 'medium'),
  ('Pada impedance plane, setelah null dilakukan, sinyal lift-off umumnya ditampilkan sebagai:',
   '["Lingkaran tertutup","Garis horizontal","Garis vertikal","Titik diam tanpa arah"]', 1,
   'Display di-rotate sehingga lift-off menjadi garis horizontal setelah null; respon flaw kemudian memutar fasa (mendekati vertikal) sehingga mudah dibedakan dari lift-off.', 'Impedance Plane', 'easy'),
  ('Tujuan utama me-rotate display ET sehingga lift-off horizontal dan flaw vertikal adalah:',
   '["Menaikkan frekuensi efektif probe","Mengubah conductivity material","Memudahkan diskriminasi sinyal flaw dari gangguan lift-off","Menghilangkan kebutuhan reference standard"]', 2,
   'Rotasi memisahkan arah lift-off (horizontal) dari flaw (vertikal) sehingga operator dapat mengevaluasi flaw tanpa terganggu variasi lift-off.', 'Impedance Plane', 'easy'),
  ('Konsep mixing dua frekuensi A - k*B(theta) terutama digunakan untuk:',
   '["Membatalkan sinyal support plate / lift-off","Menambah amplitudo defect kecil","Mengubah skin depth tanpa mengubah frekuensi","Mengkalibrasi conductivity meter"]', 0,
   'Mixing mengatur k dan theta agar sinyal gangguan (support plate/lift-off) pada channel referensi B membatalkan gangguan pada channel A, menyisakan sinyal defect bersih.', 'Multi-frekuensi', 'medium'),
  ('Heat exchanger dengan beberapa tube support plate dan kebutuhan deteksi defect tepat di bawahnya biasanya memerlukan:',
   '["Single-frequency saja","Two-frequency tanpa mixing","Hanya DC magnetization","Three-frequency mixing"]', 3,
   'Geometry kompleks dengan banyak support plate umumnya butuh three-frequency mixing untuk membatalkan sinyal TSP dan tetap mempertahankan sensitivitas defect di bawahnya.', 'Multi-frekuensi', 'medium'),
  ('Probe ET yang paling tepat untuk inspeksi crack pada lubang fastener (fastener-hole) struktur aerospace adalah:',
   '["Bobbin differential","Encircling coil","Rotating (fastener-hole) probe","MFL pig"]', 2,
   'Rotating probe dirancang memindai dinding lubang fastener secara melingkar untuk mendeteksi crack radial — aplikasi klasik aerospace.', 'Probe & Aplikasi', 'easy'),
  ('Standar yang secara spesifik menjadi guide untuk examination dengan eddy current array adalah:',
   '["ASTM E243","ASTM E2884","ASTM E309","ASME V Article 6"]', 1,
   'ASTM E2884 adalah guide untuk eddy current array examination. E243 untuk Cu-alloy tube, E309 untuk bobbin tube dengan magnetic saturation, ASME V Article 6 adalah PT.', 'Code & Standar', 'medium'),
  ('Keunggulan utama probe array (mis. ASTM E2884) dibanding bobbin konvensional adalah:',
   '["Tidak perlu reference standard","Tidak terpengaruh lift-off sama sekali","Penetrasi otomatis full wall pada ferromagnetic","Coverage lebar dengan C-scan tanpa rotasi mekanik"]', 3,
   'Array memberi coverage lebar dan imaging C-scan tanpa rotasi mekanik, mempercepat scan dan memperbaiki deteksi defect circumferential maupun lokasi.', 'Probe & Aplikasi', 'medium'),
  ('Untuk inspeksi tube ferromagnetik (mis. carbon steel feedwater heater), metode yang paling sesuai adalah:',
   '["RFT (Remote Field Testing)","Conventional bobbin ET tanpa modifikasi","Conductivity sorting","Surface array pada OD"]', 0,
   'RFT bekerja secara through-transmission pada tube ferromagnetic dan memberi penetrasi mendekati full wall; bobbin konvensional tidak efektif pada material magnetik tanpa saturasi.', 'Metode Alternatif', 'medium'),
  ('Karakteristik utama RFT yang dipakai untuk sizing defect adalah:',
   '["Amplitudo = kedalaman secara linear","Lift-off = kedalaman","Phase = depth (kedalaman dari fasa)","Frekuensi = kedalaman"]', 2,
   'Pada RFT, phase lag berkorelasi dengan kedalaman/wall loss; sizing utamanya berbasis fasa (phase = depth), dan sensitivitas ID/OD hampir sama.', 'Metode Alternatif', 'hard'),
  ('IRIS (Internal Rotary Inspection System) berbeda dari ET karena IRIS:',
   '["Tidak perlu probe masuk ke tube","Berbasis ultrasonic dan butuh water coupling","Hanya untuk material non-konduktif","Mengandalkan magnetic flux leakage"]', 1,
   'IRIS adalah metode ultrasonic dengan rotating mirror berbasis water coupling; akurat untuk pengukuran ketebalan dinding tetapi lambat dan memerlukan tube bersih.', 'Metode Alternatif', 'medium'),
  ('MFL (Magnetic Flux Leakage) paling tepat dipakai untuk:',
   '["Sizing crack tight pada Al aerospace","Conductivity sorting paduan tembaga","Inspeksi cepat pipeline/tube ferromagnetik untuk metal loss","Pengukuran lift-off non-magnetik"]', 2,
   'MFL memanfaatkan kebocoran fluks pada material ferromagnetic untuk mendeteksi metal loss/pitting secara cepat, umum pada pipeline (pig) dan tube.', 'Metode Alternatif', 'medium'),
  ('Article ASME Section V yang khusus membahas eddy current examination, T-820 technique, reference standard, dan kalibrasi adalah:',
   '["Article 4","Article 6","Article 7","Article 8"]', 3,
   'ASME Section V Article 8 mengatur eddy current examination, termasuk T-820 technique, reference standard, dan persyaratan kalibrasi. Article 4=UT, 6=PT, 7=MT.', 'Code & Standar', 'easy'),
  ('ASTM E309 secara spesifik mengatur examination bobbin tube dengan fitur penting:',
   '["Magnetic saturation","Rotating fastener probe","Ultrasonic coupling","Conductivity sorting"]', 0,
   'ASTM E309 adalah praktik eddy current bobbin tube examination dengan magnetic saturation, memungkinkan inspeksi material yang sedikit/marginally magnetik.', 'Code & Standar', 'hard'),
  ('Reference standard untuk kalibrasi tube ET tipikal memuat artificial discontinuity berupa:',
   '["Hanya satu through-hole tunggal","Hanya retakan alami acak","EDM notch / flat-bottom hole / through-hole pada kedalaman bertingkat","Cat warna sebagai penanda"]', 2,
   'Reference standard umumnya berisi EDM notch, flat-bottom hole, dan through-hole pada kedalaman bertingkat (mis. 20/40/60/80% wall) untuk membentuk kurva kalibrasi/sizing.', 'Kalibrasi', 'medium'),
  ('Standar ISO yang mengatur prinsip umum (general principles) eddy current testing adalah:',
   '["ISO 9712","ISO 15549","ISO 15548","ISO 17025"]', 1,
   'ISO 15549 mengatur general principles ET; ISO 15548 berkaitan dengan equipment characteristics ET; ISO 9712 sertifikasi personel; ISO 17025 kompetensi laboratorium.', 'Code & Standar', 'hard'),
  ('Siapa/apa yang menetapkan kriteria acceptance (mis. plug/repair pada % wall loss tertentu) untuk inspeksi tube ET?',
   '["Operator ET secara bebas di lapangan","Pabrikan probe","Referencing code/spec atau owner","Software akuisisi otomatis"]', 2,
   'Kriteria acceptance (mis. plug/repair pada 40-50% wall) ditetapkan oleh referencing code/spec atau owner, bukan oleh operator atau perangkat lunak.', 'Procedure & Evaluasi', 'medium'),
  ('Pada indikasi tube ET sebesar 60% wall loss tepat di bawah tube support plate, langkah evaluasi yang paling benar adalah:',
   '["Langsung tolak tanpa verifikasi","Abaikan karena dekat support plate","Naikkan lift-off agar sinyal hilang","Gunakan mixing untuk membatalkan sinyal TSP lalu konfirmasi & size, evaluasi terhadap acceptance"]', 3,
   'Sinyal di bawah TSP harus dipisahkan dengan mixing/multi-frekuensi untuk konfirmasi defect, kemudian di-size dan dievaluasi terhadap kriteria acceptance (60% biasanya melebihi ambang plug).', 'Case Study', 'hard'),
  ('Differential bobbin probe dibanding absolute probe lebih unggul untuk:',
   '["Mendeteksi defect lokal kecil dan menekan drift temperatur","Mendeteksi gradual/long wall loss","Mengukur conductivity absolut","Inspeksi material ferromagnetik tanpa saturasi"]', 0,
   'Differential menonjolkan perubahan lokal (pit/crack pendek) dan menekan drift termal/gradual; absolute lebih baik untuk gradual/long wall loss dan pengukuran absolut.', 'Probe & Aplikasi', 'medium'),
  ('Conductivity sorting %IACS pada aerospace paling sering digunakan untuk:',
   '["Mengukur kekasaran permukaan","Menentukan skin depth absolut","Mendeteksi heat damage / verifikasi alloy & temper pada Al","Mengganti reference standard"]', 2,
   'Conductivity %IACS sensitif terhadap perubahan paduan/temper dan kerusakan termal pada aluminium, sehingga dipakai untuk verifikasi alloy/temper dan deteksi heat damage.', 'Probe & Aplikasi', 'medium'),
  ('Saat kalibrasi tube ET, kurva sizing kedalaman dibuat dengan cara:',
   '["Mengasumsikan amplitudo selalu linear terhadap kedalaman","Memakai satu reference hole saja","Mengabaikan fasa dan hanya pakai amplitudo","Mengukur fasa pada notch/lubang kedalaman bertingkat (mis. 20/40/60/80%) lalu membuat kurva fasa-vs-kedalaman"]', 3,
   'Sizing depth pada tube ET utamanya berbasis fasa; kurva fasa-vs-kedalaman dibentuk dari reference standard dengan kedalaman bertingkat, lalu indikasi lapangan diinterpolasi.', 'Kalibrasi', 'hard'),
  ('Sebelum sizing, hal kritis yang harus dilakukan operator ET Level II terhadap indikasi adalah:',
   '["Langsung melaporkan sebagai crack","Menghapus indikasi dari rekaman","Membedakan defect sejati dari sinyal geometry (dent, support plate, baffle)","Menaikkan gain hingga indikasi hilang"]', 2,
   'Operator harus mendiskriminasi defect sejati dari sinyal geometry (dent, TSP, baffle, tube end) menggunakan fasa/mixing sebelum melakukan sizing dan evaluasi.', 'Procedure & Evaluasi', 'medium'),
  ('Isi minimum sebuah prosedur ET Level II yang dikualifikasi mencakup, antara lain:',
   '["Hanya nama operator dan tanggal","Scope, peralatan/probe, frekuensi & mixing, reference standard, scanning speed, recording threshold, dan kriteria acceptance","Hanya merek instrumen","Hanya hasil akhir tanpa parameter"]', 1,
   'Prosedur ET Level II harus menetapkan scope/material, peralatan & probe, frekuensi (termasuk mixing), reference standard, teknik null/rotasi, scanning speed, recording threshold, kriteria evaluasi, dan acceptance dari referencing code.', 'Procedure & Evaluasi', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 10 AND ls."orderIndex" = 4 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;


