-- ET-L2 Module 11 mini-quiz (60 questions, step 1)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'ET-L2' AND m."orderIndex" = 11 AND ls."orderIndex" = 1 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'ET', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Rumus standar kedalaman penetrasi (skin depth) δ pada Eddy Current Testing adalah...',
   '["δ = √(π·f·μ·σ)","δ = 1 / √(π·f·μ·σ)","δ = f·μ·σ / π","δ = π / (f·μ·σ)"]', 1,
   'Skin depth standar δ = 1/√(π·f·μ·σ). Penetrasi berbanding terbalik dengan akar frekuensi (f), permeabilitas (μ), dan konduktivitas (σ). Menaikkan salah satunya akan mengurangi penetrasi.', 'Fisika ET', 'easy'),
  ('Menggunakan rumus praktis δ[mm] ≈ 21/√(f[kHz]·σ[%IACS]·μ_r), berapa perkiraan skin depth pada aluminium (σ=40 %IACS, μ_r=1) pada 100 kHz?',
   '["≈ 0.033 mm","≈ 3.3 mm","≈ 0.33 mm","≈ 1.0 mm"]', 2,
   'δ = 21/√(100·40·1) = 21/√4000 = 21/63.2 ≈ 0.33 mm. Ini adalah anchor value yang penting untuk Al pada 100 kHz, 40 %IACS.', 'Fisika ET', 'medium'),
  ('Jika frekuensi inspeksi dinaikkan menjadi 4 kali lipat (tanpa mengubah material), kedalaman penetrasi (skin depth) akan menjadi...',
   '["Dua kali semula","Empat kali semula","Seperempat dari semula","Setengah dari semula"]', 3,
   'δ berbanding terbalik dengan √f. Frekuensi naik 4× → √4 = 2 → penetrasi menjadi 1/2 dari semula. Naikkan frekuensi untuk cacat dekat permukaan, turunkan untuk cacat lebih dalam.', 'Fisika ET', 'medium'),
  ('Phase lag β untuk cacat pada kedalaman x diperkirakan dengan β ≈ x/δ (radian). Implikasinya pada impedance plane adalah...',
   '["Cacat yang lebih dalam menghasilkan rotasi fasa (phase rotation) yang lebih besar","Cacat yang lebih dalam tidak mengubah fasa sama sekali","Cacat yang lebih dalam selalu menghasilkan amplitudo lebih besar","Phase lag hanya bergantung pada lift-off, bukan kedalaman"]', 0,
   'β ≈ x/δ rad: semakin dalam cacat (x besar), semakin besar phase lag/rotasi fasa pada impedance plane. Inilah dasar penilaian kedalaman cacat dari sudut sinyal.', 'Impedance Plane', 'medium'),
  ('Pada impedance plane setelah proses null/balance, sinyal lift-off (probe menjauh dari permukaan) bergerak pada arah...',
   '["Vertikal","Horizontal","45 derajat ke atas selalu","Membentuk lingkaran penuh"]', 1,
   'Konvensi: setelah null, lift-off bergerak horizontal sedangkan sinyal cacat (flaw) cenderung vertikal. Pemisahan sudut antara keduanya adalah kunci membedakan lift-off palsu dari indikasi cacat.', 'Impedance Plane', 'easy'),
  ('Tujuan utama rotasi fasa (phase rotation) saat setup instrumen ET adalah...',
   '["Meningkatkan tegangan eksitasi coil","Mengubah frekuensi operasi probe","Memposisikan sinyal lift-off horizontal sehingga sinyal cacat menonjol pada arah vertikal","Menghapus seluruh sinyal dari layar"]', 2,
   'Phase rotation diatur agar lift-off jatuh horizontal; dengan demikian respons cacat yang berbeda fasa menjadi terpisah dan mudah dikenali secara vertikal. Ini memisahkan variabel lift-off dari sinyal cacat.', 'Impedance Plane', 'easy'),
  ('Teknik multi-frequency mixing dasar menggunakan persamaan sinyal campuran berbentuk...',
   '["A + B + C dijumlahkan tanpa pembobotan","A × B dikalikan langsung","A/B sebagai rasio amplitudo","A − k·B(θ), untuk menghilangkan sinyal struktur pendukung/lift-off"]', 3,
   'Mix dua-frekuensi: Mix = A − k·B(θ). Faktor k dan rotasi fasa θ disesuaikan agar sinyal yang tidak diinginkan (mis. support plate atau lift-off) tersuppress, menyisakan sinyal cacat.', 'Teknik', 'medium'),
  ('Untuk menekan (suppress) sinyal dari DUA struktur pengganggu yang berbeda secara bersamaan, jumlah frekuensi minimum yang umumnya diperlukan adalah...',
   '["3 frekuensi (3-frequency mix)","1 frekuensi sudah cukup","2 frekuensi sudah cukup untuk dua struktur","Minimal 5 frekuensi"]', 0,
   'Mix dua-frekuensi menghilangkan satu variabel pengganggu. Untuk dua struktur berbeda (mis. support plate + dukungan kedua), diperlukan 3-frequency mix; tiap mix tambahan menghapus satu variabel tambahan.', 'Teknik', 'hard'),
  ('Parameter k pada persamaan mix A − k·B(θ) berfungsi untuk...',
   '["Mengatur kecepatan scanning probe","Menyamakan amplitudo sinyal pengganggu antara dua frekuensi sebelum dikurangkan","Menentukan gain digital tampilan akhir saja","Memilih jenis probe yang digunakan"]', 1,
   'k adalah faktor bobot amplitudo, dan θ adalah rotasi fasa. Keduanya disetel pada sinyal kalibrasi (mis. support plate) agar respons pengganggu di kedua frekuensi sama besar dan berlawanan, sehingga saling meniadakan saat dikurangkan.', 'Teknik', 'medium'),
  ('Pada inspeksi tube heat exchanger dengan bobbin probe, sinyal support plate dapat menutupi cacat di bawahnya. Solusi multi-frequency yang tepat adalah...',
   '["Menaikkan kecepatan tarik probe agar support plate tidak terdeteksi","Mematikan kanal absolute dan hanya pakai amplitudo mentah","Menggunakan dua frekuensi dan mix A − k·B(θ) untuk menekan respons support plate","Menggunakan probe penetrant"]', 2,
   'Frekuensi kedua dipilih agar merespons kuat pada support plate; dengan mix A − k·B(θ), respons support plate ditiadakan sehingga cacat di lokasi support plate (sering kritis) menjadi terlihat.', 'Teknik', 'hard'),
  ('Probe bobbin tipe DIFFERENTIAL dibandingkan tipe ABSOLUTE memiliki keunggulan...',
   '["Lebih baik mendeteksi penipisan dinding bertahap yang panjang","Sangat sensitif terhadap cacat lokal pendek dan menekan variasi gradual (drift suhu, perubahan dimensi perlahan)","Tidak terpengaruh sama sekali oleh cacat","Hanya bisa dipakai pada material ferromagnetik"]', 1,
   'Differential (dua koil berlawanan) sangat peka pada perubahan lokal/tajam dan menolak variasi gradual. Absolute lebih baik untuk perubahan bertahap/menyeluruh seperti general wall thinning. Keduanya saling melengkapi.', 'Probe', 'medium'),
  ('Jenis probe ET yang dirancang khusus untuk inspeksi lubang fastener pada struktur aerospace adalah...',
   '["Bobbin encircling probe","Surface pancake probe besar","RFT through-transmission probe","Rotating (bolt-hole / fastener-hole) probe"]', 3,
   'Rotating probe (bolt-hole scanner) dimasukkan ke dalam lubang dan diputar untuk memetakan retak radial dari dinding lubang fastener — aplikasi khas aerospace untuk fatigue crack di sekitar lubang.', 'Probe', 'easy'),
  ('Standar utama yang mengatur eddy current array (ECA) probe adalah...',
   '["ASTM E2884","ASTM E309","ASTM E243","ASME Section IX"]', 0,
   'ASTM E2884 adalah standard guide untuk eddy current array. ASTM E309 (bobbin tube + magnetic saturation), E243 (Cu tube), dan ASME Section IX (welding/brazing qualification, bukan ECA).', 'Kode & Standar', 'medium'),
  ('Keunggulan utama array probe dibandingkan single-coil probe untuk pemindaian permukaan adalah...',
   '["Penetrasi selalu jauh lebih dalam tanpa mengubah frekuensi","Cakupan area lebih lebar dalam satu lewatan dan menghasilkan C-scan untuk imaging","Tidak memerlukan kalibrasi sama sekali","Menghilangkan kebutuhan analisis impedance plane"]', 1,
   'Array (banyak koil dengan multiplexing) menutup lebar besar sekali pindai, mengurangi waktu, dan menghasilkan C-scan/imaging untuk sizing dan dokumentasi. Penetrasi tetap diatur oleh frekuensi.', 'Probe', 'easy'),
  ('Pada array probe, untuk meminimalkan interferensi (cross-talk) antar elemen koil yang bersebelahan saat aktif, teknik yang umum digunakan adalah...',
   '["Mengaktifkan seluruh elemen pada fasa identik secara bersamaan","Menonaktifkan rotasi fasa pada semua kanal","Multiplexing / time-sharing aktivasi elemen secara bergiliran","Menggunakan satu frekuensi sangat rendah untuk semua elemen"]', 2,
   'Cross-talk dikendalikan dengan multiplexing (elemen diaktifkan bergiliran/time-shared) dan pengaturan topologi koil. Ini memungkinkan kerapatan elemen tinggi tanpa interferensi medan antar koil bersebelahan.', 'Probe', 'hard'),
  ('Probe ENCIRCLING (feed-through) paling tepat digunakan untuk inspeksi...',
   '["Permukaan datar pelat besar dengan satu titik kontak","Lubang fastener dengan pemutaran internal","Batang/kawat/tubing yang dilewatkan melalui koil dari sisi luar (OD)","Permukaan internal tube dari dalam saja"]', 2,
   'Encircling probe mengelilingi produk bentuk silinder (bar, wire, tube dari OD) yang lewat di dalam koil — cocok untuk inspeksi produksi kontinu. Probe bobbin masuk ke dalam (ID) tube; rotating untuk lubang.', 'Probe', 'medium'),
  ('Pada impedance plane, dua sinyal memiliki amplitudo sama tetapi sudut fasa berbeda 30°. Interpretasi yang paling tepat adalah...',
   '["Keduanya pasti cacat identik karena amplitudonya sama","Keduanya berbeda kedalaman/jenis karena fasa terkait phase lag (kedalaman) cacat","Fasa tidak membawa informasi, hanya amplitudo yang penting","Perbedaan fasa hanya disebabkan oleh kebisingan elektronik"]', 1,
   'Pada ET, sudut fasa membawa informasi kedalaman (β ≈ x/δ). Amplitudo sama tetapi fasa beda menunjukkan kedalaman/karakter berbeda. Inilah dasar pemisahan OD vs ID flaw dan sizing kedalaman.', 'Impedance Plane', 'hard'),
  ('Pada inspeksi tube non-ferromagnetik, perbedaan sudut fasa antara cacat sisi ID dan sisi OD muncul karena...',
   '["ID dan OD selalu menghasilkan fasa identik","OD selalu memberi amplitudo lebih besar dari ID","Fasa hanya bergantung pada konduktivitas, bukan posisi cacat","Eddy current lebih lemah di OD (lebih jauh dari koil ID) sehingga phase lag berbeda terhadap kedalaman"]', 3,
   'Dengan bobbin dari ID, eddy current meluruh ke arah OD; cacat OD berada lebih ''dalam'' (phase lag lebih besar) dibanding cacat ID. Kalibrasi pada ASME calibration standard (lubang/notch ID & OD) memetakan sudut fasa ini.', 'Impedance Plane', 'hard'),
  ('Mengapa lift-off harus dikendalikan/diminimalkan saat inspeksi surface dengan probe absolute?',
   '["Variasi lift-off menghasilkan sinyal besar yang dapat menutupi atau meniru indikasi cacat","Lift-off menambah penetrasi sehingga selalu menguntungkan","Lift-off tidak berpengaruh apa pun pada sinyal ET","Lift-off hanya mempengaruhi probe ferromagnetik"]', 0,
   'Perubahan lift-off menghasilkan sinyal besar di arah horizontal; jika tidak dikendalikan/diputar dengan benar, ia dapat menutupi cacat. Itulah mengapa lift-off diposisikan horizontal lewat phase rotation dan dijaga konstan.', 'Impedance Plane', 'easy'),
  ('Untuk inspeksi tube HEAT EXCHANGER berbahan FERROMAGNETIK (mis. carbon steel), teknik ET konvensional bobbin kurang efektif. Teknik yang TEPAT adalah...',
   '["Bobbin differential frekuensi tinggi tanpa modifikasi","RFT (Remote Field Testing)","Surface pancake probe dari luar","Penetrant testing dari ID"]', 1,
   'Pada tube ferromagnetik, eddy current konvensional sulit menembus karena permeabilitas tinggi. RFT memakai prinsip through-transmission medan jauh, menembus hampir seluruh dinding dengan sensitivitas OD/ID hampir sama.', 'Aplikasi', 'medium'),
  ('Karakteristik khas Remote Field Testing (RFT) pada tube ferromagnetik adalah...',
   '["Hanya sensitif terhadap cacat ID, OD tidak terdeteksi","Mengukur ketebalan dinding secara ultrasonik","Sensitivitas OD dan ID hampir sama, dan kedalaman cacat dikorelasikan dengan phase lag","Memerlukan couplant cairan seperti UT"]', 2,
   'RFT (through-transmission medan jauh) menembus ~seluruh dinding sehingga sensitivitas OD≈ID; kedalaman/keparahan cacat dinilai dari phase lag. RFT adalah elektromagnetik, tidak memerlukan couplant.', 'Aplikasi', 'medium'),
  ('Teknik untuk pengukuran KETEBALAN DINDING tube yang sangat AKURAT (namun relatif lambat dan butuh couplant) adalah...',
   '["MFL (Magnetic Flux Leakage)","Bobbin absolute single-frequency","IRIS (Internal Rotary Inspection System, berbasis ultrasonik)","Surface array C-scan"]', 2,
   'IRIS adalah teknik ultrasonik rotari internal yang memberikan pengukuran ketebalan dinding akurat dan profil melingkar; kelemahannya lambat dan butuh couplant (tube harus bersih dan terisi air).', 'Aplikasi', 'medium'),
  ('Teknik MFL (Magnetic Flux Leakage) untuk tube ferromagnetik paling tepat dideskripsikan sebagai...',
   '["Cepat untuk mendeteksi pitting/wall loss lokal pada material ferromagnetik","Teknik ultrasonik yang sangat lambat","Hanya bekerja pada material non-ferromagnetik","Mengukur konduktivitas %IACS"]', 0,
   'MFL memagnetisasi tube ferromagnetik hingga jenuh; kehilangan logam (pit/wall loss) menyebabkan kebocoran fluks yang terdeteksi sensor. MFL cepat untuk screening pitting/wall loss, sering melengkapi IRIS untuk konfirmasi.', 'Aplikasi', 'medium'),
  ('Strategi inspeksi heat exchanger ferromagnetik yang umum menggabungkan MFL dan IRIS adalah...',
   '["IRIS untuk semua tube karena paling cepat","MFL untuk mengukur ketebalan presisi setiap tube","MFL untuk screening cepat seluruh tube, lalu IRIS untuk pengukuran akurat pada tube yang dicurigai","Keduanya tidak boleh digabung dalam satu program"]', 2,
   'Pendekatan efisien: MFL/RFT sebagai screening cepat seluruh bundle, kemudian IRIS (akurat tapi lambat) hanya pada tube yang memberi indikasi untuk pengukuran ketebalan dan sizing yang presisi.', 'Prosedur', 'hard'),
  ('Conductivity sorting menggunakan satuan %IACS terutama dipakai di aerospace untuk...',
   '["Verifikasi paduan (alloy) dan kondisi heat-treat / deteksi heat damage pada aluminium","Mengukur ketebalan cat secara langsung","Mendeteksi retak fatigue di lubang fastener","Mengukur kekasaran permukaan"]', 0,
   'Konduktivitas (%IACS) sensitif terhadap komposisi paduan dan kondisi temper/heat-treat. Pada aerospace dipakai untuk alloy sorting dan mendeteksi heat damage (mis. overheating) yang mengubah konduktivitas.', 'Aplikasi', 'medium'),
  ('Pengukuran ketebalan coating (cat/anodize) non-konduktif di atas substrat logam dengan ET memanfaatkan...',
   '["Perubahan konduktivitas substrat","Efek lift-off — ketebalan coating setara dengan jarak angkat probe","Phase lag dari cacat dalam","Saturasi magnetik substrat"]', 1,
   'Coating non-konduktif menambah jarak antara koil dan substrat = lift-off terkontrol. Instrumen dikalibrasi sehingga lift-off (sinyal horizontal) dibaca sebagai ketebalan coating. Substrat konduktif harus seragam.', 'Aplikasi', 'medium'),
  ('Saat conductivity sorting aluminium, mengapa suhu komponen dan probe harus diperhatikan?',
   '["Suhu tidak mempengaruhi konduktivitas sama sekali","Suhu hanya mempengaruhi material ferromagnetik","Pembacaan %IACS hanya valid di atas 100 °C","Konduktivitas logam berubah terhadap suhu, sehingga koreksi/kompensasi suhu diperlukan untuk pembacaan %IACS akurat"]', 3,
   'Konduktivitas listrik logam menurun saat suhu naik. Conductivity meter mengasumsikan suhu referensi (mis. 20 °C); pembacaan harus dikompensasi suhu agar sorting alloy/heat-treat valid.', 'Aplikasi', 'hard'),
  ('Pada inspeksi fastener hole dengan rotating probe, frekuensi dipilih relatif tinggi terutama untuk...',
   '["Memusatkan sensitivitas pada retak yang muncul di permukaan dinding lubang dan meningkatkan resolusi","Menembus jauh ke material di sekitar lubang","Menghilangkan kebutuhan kalibrasi notch","Mengurangi resolusi agar sinyal lebih halus"]', 0,
   'Retak fatigue biasanya tumbuh dari permukaan dinding lubang. Frekuensi tinggi memberi penetrasi dangkal namun resolusi tinggi dan sensitivitas kuat di permukaan, ideal untuk mendeteksi retak permukaan lubang fastener.', 'Teknik', 'medium'),
  ('Untuk membedakan sinyal RETAK dari sinyal LIFT-OFF di lubang fastener saat probe sedikit goyang, parameter yang paling diandalkan adalah...',
   '["Hanya amplitudo absolut sinyal","Sudut fasa sinyal (retak berbeda fasa dari lift-off horizontal)","Warna tampilan layar","Kecepatan putaran probe saja"]', 1,
   'Karena lift-off diposisikan horizontal lewat phase rotation, retak yang muncul pada sudut fasa berbeda (lebih vertikal) dapat dipisahkan dari noise lift-off. Sudut fasa, bukan amplitudo semata, yang menentukan.', 'Impedance Plane', 'medium'),
  ('Dokumen yang menjadi acuan teknik ET pada pengelasan/komponen menurut ASME Boiler & Pressure Vessel Code adalah...',
   '["ASME Section V, Article 4","ASME Section V, Article 8","ASME Section II, Part C","ASME Section IX"]', 1,
   'ASME Section V, Article 8 mengatur Eddy Current Examination. Article 4 = UT, Section II Part C = welding consumables, Section IX = welding/brazing qualification.', 'Kode & Standar', 'medium'),
  ('ASTM E309 berkaitan dengan...',
   '["Eddy current pada copper/copper-alloy tube","Eddy current array (ECA)","Eddy current examination tube baja (ferromagnetik) menggunakan saturasi magnetik","Radiographic testing pelat"]', 2,
   'ASTM E309 = ET tube baja dengan magnetic saturation (untuk menekan efek permeabilitas pada material ferromagnetik). E243 = Cu/Cu-alloy tube, E2884 = ECA.', 'Kode & Standar', 'medium'),
  ('ASTM E243 adalah standar praktik untuk pemeriksaan eddy current pada...',
   '["Tube tembaga dan paduan tembaga (copper & copper-alloy)","Tube baja karbon ferromagnetik","Eddy current array surface scanning","Pengukuran konduktivitas aluminium"]', 0,
   'ASTM E243 mengatur ET seamless copper and copper-alloy tubes (mis. tube kondensor). E309 untuk tube baja dengan saturasi, E2884 untuk array.', 'Kode & Standar', 'medium'),
  ('Standar ISO yang relevan untuk kualifikasi peralatan/karakterisasi instrumen dan probe ET adalah...',
   '["ISO 9001 dan ISO 14001","ISO 17025 untuk laboratorium kalibrasi saja","ISO 3834 untuk fabrikasi las","ISO 15548 (peralatan) dan ISO 15549 (prinsip umum ET)"]', 3,
   'ISO 15549 menetapkan prinsip umum eddy current testing; seri ISO 15548 mengatur karakterisasi/verifikasi peralatan ET. ISO 9712 mengatur kualifikasi personel NDT.', 'Kode & Standar', 'hard'),
  ('Mengapa pada inspeksi tube baja ferromagnetik dengan eddy current (ASTM E309) digunakan saturasi magnetik?',
   '["Saturasi menekan permeabilitas efektif sehingga eddy current dapat menembus dan noise magnetik berkurang","Saturasi meningkatkan permeabilitas agar penetrasi lebih dalam","Saturasi menghasilkan couplant untuk sinyal","Saturasi mengubah material menjadi non-konduktif"]', 0,
   'Permeabilitas tinggi & variasinya menghasilkan noise dan penetrasi sangat dangkal. Saturasi magnetik memaksa material ke kondisi μ efektif rendah/stabil, sehingga eddy current dapat bekerja dan noise permeabilitas berkurang.', 'Kode & Standar', 'hard'),
  ('Dalam pengembangan prosedur ET, siapa/apa yang menetapkan kriteria penerimaan (acceptance criteria) cacat?',
   '["Operator ET secara bebas saat inspeksi","Produsen instrumen ET","Referencing code dan/atau owner/customer (mis. % wall loss untuk plugging)","Selalu 100% bebas indikasi tanpa pengecualian"]', 2,
   'Kriteria penerimaan tidak dibuat operator; ditetapkan oleh referencing code/standar dan/atau owner. Contoh umum heat exchanger: plug tube pada wall loss 40–50% (sesuai spesifikasi pemilik).', 'Acceptance', 'medium'),
  ('Pada banyak program heat exchanger, ambang batas (threshold) untuk PLUGGING tube biasanya berada pada rentang...',
   '["Sekitar 5% wall loss","Sekitar 40–50% wall loss (sesuai code/owner)","Tepat 100% (tube bocor) saja","Tidak pernah ada batas, semua tube dipertahankan"]', 1,
   'Acceptance ditetapkan referencing code/owner; nilai yang lazim untuk plugging adalah 40–50% wall loss. Nilai pasti tetap mengacu pada spesifikasi pemilik/desain tekanan.', 'Acceptance', 'medium'),
  ('Elemen yang WAJIB ada dalam prosedur ET tertulis menurut praktik kode (mis. ASME V Art. 8) mencakup...',
   '["Hanya nama operator dan tanggal inspeksi","Hanya merek instrumen tanpa parameter teknis","Hanya jumlah tube tanpa parameter setup","Jenis/ukuran probe, frekuensi, instrumen, standar kalibrasi, teknik scanning, dan kriteria penerimaan"]', 3,
   'Prosedur ET harus menetapkan variabel esensial: probe (jenis/ukuran/frekuensi), instrumen, calibration standard, teknik/kecepatan scanning, metode evaluasi, dan acceptance criteria — agar inspeksi dapat diulang dan diaudit.', 'Prosedur', 'medium'),
  ('Calibration/reference standard untuk inspeksi tube heat exchanger biasanya berisi reflektor buatan berupa...',
   '["Through-hole, flat-bottom hole / grooves OD & ID, dan ASME-style drilled holes dengan kedalaman diketahui","Retak alami acak tanpa dimensi tercatat","Hanya satu lubang tunggal tanpa OD/ID notch","Lapisan cat dengan ketebalan acak"]', 0,
   'Standar kalibrasi tube punya reflektor berdimensi diketahui (through-hole, flat-bottom holes, OD/ID grooves) untuk menyetel phase angle vs depth dan amplitude, sehingga sizing dan diskriminasi OD/ID dapat dikalibrasi.', 'Kalibrasi', 'medium'),
  ('Saat menyetel phase pada calibration standard tube non-ferromagnetik, sinyal dari through-wall hole (100%) dijadikan acuan untuk...',
   '["Menentukan kecepatan tarik probe maksimum","Menetapkan sudut fasa referensi 100% dan memetakan kedalaman cacat lain relatif terhadapnya","Mengukur konduktivitas %IACS material","Menonaktifkan kanal differential"]', 1,
   'Through-wall hole memberi sinyal 100% sebagai anchor sudut fasa. Reflektor ID/OD lain dengan kedalaman diketahui dipakai membentuk phase-vs-depth curve untuk sizing kedalaman cacat lapangan.', 'Kalibrasi', 'hard'),
  ('Pada inspeksi heat exchanger, posisi ''support plate'' yang muncul berulang di sinyal bobbin sebaiknya...',
   '["Diidentifikasi dan dikorelasikan dengan landmark/peta tube karena cacat di dekat support plate sering kritis","Diabaikan total karena selalu tidak relevan","Dihapus dari rekaman agar sinyal bersih","Dianggap sebagai cacat through-wall otomatis"]', 0,
   'Support plate menjadi landmark untuk menentukan posisi aksial cacat. Daerah di bawah support plate rawan korosi/erosi; mix multi-frequency dipakai untuk menekan sinyal support plate agar cacat di sana terdeteksi.', 'Interpretasi', 'medium'),
  ('Indikasi ''dent'' (penyok) pada tube biasanya dibedakan dari cacat metal-loss karena...',
   '["Dent selalu menghasilkan sinyal 100% through-wall","Dent menghasilkan sinyal khas terkait perubahan geometri/lift-off internal, bukan kehilangan logam aktual","Dent tidak menghasilkan sinyal apa pun","Dent hanya terdeteksi oleh IRIS, tak pernah oleh ET"]', 1,
   'Dent mengubah geometri (jarak probe-dinding) dan menghasilkan sinyal mirip lift-off/geometri tanpa metal loss. Analisis fasa dan korelasi multi-frequency membantu membedakannya dari pit/wall loss sejati.', 'Interpretasi', 'hard'),
  ('Sinyal pada kanal differential yang menunjukkan pola ''figure-8'' simetris pada bobbin tube umumnya menandakan...',
   '["Penipisan dinding gradual yang sangat panjang","Lift-off konstan tanpa cacat","Cacat lokal pendek (mis. pit) yang dilewati kedua koil differential","Saturasi magnetik penuh material"]', 2,
   'Koil differential menghasilkan respons ganda berlawanan saat tiap koil melewati cacat lokal, membentuk pola figure-8/lissajous khas untuk indikasi diskret seperti pit. Sudut & amplitudo lobus dipakai untuk sizing.', 'Interpretasi', 'hard'),
  ('Mengapa kecepatan tarik (pull speed) probe bobbin harus dikontrol dan dibatasi maksimum dalam prosedur?',
   '["Kecepatan berlebih dapat menurunkan sampling/resolusi dan menyebabkan cacat kecil terlewat atau sinyal terdistorsi","Kecepatan tinggi meningkatkan penetrasi sinyal","Kecepatan tidak berpengaruh pada hasil ET sama sekali","Kecepatan tinggi memperbaiki rasio sinyal-ke-noise"]', 0,
   'Laju digitization/sampling instrumen terbatas; tarik terlalu cepat mengurangi titik data per cacat, menurunkan resolusi/amplitudo dan berisiko melewatkan cacat kecil. Prosedur menetapkan kecepatan maksimum yang divalidasi.', 'Prosedur', 'medium'),
  ('Untuk menilai apakah suatu peralatan ET memenuhi prosedur sebelum inspeksi, langkah pertama yang benar adalah...',
   '["Langsung memindai komponen produksi tanpa kalibrasi","Menyetel gain hingga layar penuh sinyal","Mengganti probe sampai sinyal hilang","Melakukan system/standardization check pada calibration standard yang sesuai dan verifikasi respons reflektor acuan"]', 3,
   'Standardisasi pada reference standard memverifikasi sistem (instrumen+probe+kabel+setting) memberi respons fasa/amplitudo benar terhadap reflektor acuan sebelum dan secara berkala selama inspeksi (interval & re-check ditetapkan prosedur).', 'Kalibrasi', 'easy'),
  ('Studi kasus: tube stainless steel kondensor menunjukkan sinyal differential dengan phase angle mendekati sudut acuan through-wall. Interpretasi paling mungkin...',
   '["Cacat sangat dalam (mendekati through-wall) — kandidat untuk evaluasi/plugging","Cacat sangat dangkal di OD","Hanya lift-off, bukan cacat","Support plate normal"]', 0,
   'Phase angle memetakan kedalaman; sudut mendekati sudut through-wall berarti cacat hampir tembus dinding. Sesuai phase-vs-depth curve, indikasi sedalam ini biasanya melebihi ambang plugging dan dievaluasi lebih lanjut.', 'Interpretasi', 'hard'),
  ('Studi kasus aerospace: dua komponen Al seharusnya identik tetapi conductivity meter membaca 35 %IACS vs 42 %IACS. Kemungkinan penyebab paling masuk akal...',
   '["Salah satu komponen berbahan baja","Perbedaan kondisi heat-treat/temper atau heat damage pada salah satu komponen","Perbedaan warna cat permukaan","Perbedaan berat komponen saja"]', 1,
   'Selisih %IACS signifikan pada paduan Al yang seharusnya sama mengindikasikan perbedaan kondisi metalurgi (temper/heat-treat) atau heat damage. Conductivity sorting memang dipakai untuk mendeteksi hal ini.', 'Aplikasi', 'medium'),
  ('Studi kasus: saat inspeksi lubang fastener multilayer aerospace, indikasi muncul hanya pada kedalaman tertentu sepanjang lubang. Hal ini paling mungkin menandakan...',
   '["Lift-off seragam di seluruh kedalaman","Perubahan konduktivitas cat luar","Retak fatigue pada interface/layer tertentu di sekitar lubang","Saturasi magnetik substrat aluminium"]', 2,
   'Indikasi terlokalisasi pada kedalaman tertentu di dinding lubang menunjukkan retak (sering fatigue) pada interface layer. Rotating probe memetakan posisi sudut & kedalaman retak untuk evaluasi.', 'Interpretasi', 'hard'),
  ('Pemilihan frekuensi inspeksi (frekuensi prima) untuk tube non-ferromagnetik sering didasarkan pada parameter f90 / depth-of-penetration agar...',
   '["Phase separation antara cacat ID dan OD optimal (umumnya target pemisahan fasa yang baik antar reflektor)","Amplitudo lift-off dimaksimalkan","Penetrasi nol sehingga hanya permukaan terbaca","Konduktivitas terukur langsung dalam %IACS"]', 0,
   'Frekuensi prima dipilih (mis. via f90 atau pedoman δ vs wall) agar pemisahan sudut fasa OD vs ID memadai untuk diskriminasi dan sizing, sambil menjaga sensitivitas terhadap cacat sepanjang dinding.', 'Prosedur', 'hard'),
  ('Pada array probe, mode operasi koil yang menempatkan driver dan pickup pada elemen berbeda untuk meningkatkan sensitivitas arah cacat disebut...',
   '["Single absolute mode","Saturasi magnetik mode","Transmit-receive (driver-pickup) topology","Couplant immersion mode"]', 2,
   'Array sering memakai topologi transmit-receive (driver-pickup) di samping mode impedance; konfigurasi pasangan koil mengatur arah sensitivitas (mis. melintang vs aksial) terhadap retak, melengkapi cakupan C-scan.', 'Probe', 'hard'),
  ('Keterbatasan mendasar Eddy Current Testing adalah...',
   '["Hanya dapat diterapkan pada material konduktif listrik","Dapat menembus material non-konduktif tebal dengan mudah","Selalu memerlukan couplant cairan","Tidak terpengaruh oleh lift-off"]', 0,
   'ET memerlukan eddy current, sehingga material harus konduktif listrik (logam). Material non-konduktif tidak dapat diinduksi eddy current. ET tanpa-kontak (tak butuh couplant) tetapi sangat dipengaruhi lift-off.', 'Prinsip Dasar', 'easy'),
  ('Hukum dasar yang menjelaskan terbentuknya eddy current akibat medan magnet AC yang berubah adalah...',
   '["Hukum Snellius tentang pembiasan","Hukum induksi Faraday (dan arah arus oleh hukum Lenz)","Hukum Hooke tentang elastisitas","Hukum Beer-Lambert tentang atenuasi"]', 1,
   'Medan magnet AC koil yang berubah menginduksi tegangan (Faraday) yang mendorong eddy current di konduktor; arahnya menentang perubahan fluks (Lenz). Cacat mengganggu eddy current dan memantul ke impedansi koil.', 'Prinsip Dasar', 'easy'),
  ('Pada material ferromagnetik, mengapa skin depth jauh lebih kecil dibanding material non-ferromagnetik pada frekuensi & konduktivitas serupa?',
   '["Konduktivitas ferromagnetik selalu nol","Permeabilitas memperbesar δ secara linear","Frekuensi otomatis turun pada ferromagnetik","Permeabilitas relatif (μ_r) yang besar memperkecil δ karena δ ∝ 1/√μ"]', 3,
   'δ ∝ 1/√μ. μ_r material ferromagnetik bisa ratusan, jauh > 1, sehingga δ menyusut drastis dan eddy current terkonsentrasi sangat dekat permukaan — alasan diperlukannya saturasi magnetik atau RFT.', 'Fisika ET', 'medium'),
  ('Sebuah cacat berada pada kedalaman x = δ (satu skin depth). Perkiraan phase lag β menggunakan β ≈ x/δ adalah...',
   '["≈ 1 radian (≈ 57°)","≈ 0 radian","≈ 3.14 radian (180°)","≈ 0.1 radian"]', 0,
   'β ≈ x/δ = δ/δ = 1 rad ≈ 57°. Pada satu skin depth, amplitudo eddy current juga turun menjadi ~37% (1/e). Phase lag bertambah ~1 rad per skin depth kedalaman.', 'Fisika ET', 'medium'),
  ('Manakah pernyataan yang BENAR tentang perbandingan RFT dan bobbin ET konvensional pada tube?',
   '["Bobbin konvensional ideal untuk carbon steel tanpa modifikasi","RFT hanya bekerja pada tembaga","RFT untuk tube ferromagnetik dengan sensitivitas OD≈ID; bobbin konvensional untuk tube non-ferromagnetik","Keduanya memerlukan couplant ultrasonik"]', 2,
   'Bobbin ET konvensional efektif pada tube non-ferromagnetik (Cu, SS, brass) dengan sensitivitas ID lebih tinggi dari OD. RFT mengatasi keterbatasan pada tube ferromagnetik dengan sensitivitas OD≈ID melalui medan jauh.', 'Aplikasi', 'medium'),
  ('Saat mengembangkan prosedur ET array untuk surface scanning weld, validasi (technique qualification) sebaiknya dilakukan dengan...',
   '["Mock-up/representative sample berisi reflektor/cacat representatif berdimensi diketahui untuk membuktikan deteksi & sizing","Langsung memakai komponen produksi tanpa sampel uji","Hanya simulasi komputer tanpa sampel fisik","Mengandalkan pengalaman operator tanpa rekaman"]', 0,
   'Kualifikasi teknik memerlukan mock-up dengan reflektor/cacat representatif (jenis, orientasi, ukuran) untuk membuktikan POD dan kemampuan sizing sesuai acceptance, sekaligus menetapkan parameter scanning dan kalibrasi.', 'Prosedur', 'hard'),
  ('Pada conductivity sorting, instrumen meter konduktivitas ET sebaiknya dikalibrasi menggunakan...',
   '["Satu blok aluminium acak tanpa nilai diketahui","Conductivity reference standards bersertifikat (mis. dua atau lebih nilai %IACS yang mengapit rentang pengukuran)","Calibration tube heat exchanger","Tidak perlu standar; pakai pembacaan udara"]', 1,
   'Conductivity meter dikalibrasi dengan reference standards bersertifikat (umumnya dua titik yang mengapit rentang, mis. ~mid & high %IACS) pada suhu referensi, untuk memastikan pembacaan %IACS akurat sebelum sorting.', 'Kalibrasi', 'medium'),
  ('Pada impedance plane, mengapa sinyal cacat permukaan tajam (crack) cenderung lebih ''vertikal'' dibanding lift-off setelah setup yang benar?',
   '["Crack tidak mempengaruhi eddy current sama sekali","Lift-off selalu vertikal dan crack horizontal","Crack menghambat aliran eddy current dengan respons fasa berbeda dari lift-off yang sudah diputar horizontal","Fasa crack identik dengan lift-off sehingga keduanya tumpang tindih"]', 2,
   'Setelah lift-off diputar horizontal, respons crack (yang menghambat aliran eddy current dengan karakter fasa berbeda) muncul terpisah secara sudut, umumnya lebih vertikal — memudahkan diskriminasi crack dari lift-off.', 'Impedance Plane', 'medium'),
  ('Manakah urutan yang benar untuk menaikkan sensitivitas terhadap cacat DEKAT PERMUKAAN pada surface ET?',
   '["Turunkan frekuensi → skin depth membesar → energi ke permukaan","Naikkan lift-off → sinyal permukaan menguat","Naikkan frekuensi → skin depth mengecil → energi terkonsentrasi di permukaan","Turunkan gain → cacat permukaan lebih terlihat"]', 2,
   'Cacat dekat permukaan paling baik dideteksi dengan frekuensi tinggi: skin depth mengecil, kerapatan eddy current di permukaan meningkat, sehingga sensitivitas dan resolusi permukaan naik. Frekuensi rendah untuk cacat dalam.', 'Teknik', 'easy'),
  ('Tujuan utama dokumentasi C-scan pada inspeksi array probe adalah...',
   '["Memberikan rekaman imaging area-terpetakan untuk evaluasi, sizing, dan ketertelusuran (traceability)","Menggantikan kebutuhan kriteria penerimaan","Mengukur konduktivitas dalam %IACS","Menghapus kebutuhan kalibrasi probe"]', 0,
   'C-scan menyajikan peta amplitudo/fasa terhadap posisi, memudahkan deteksi, sizing, dan menyediakan rekaman permanen untuk evaluasi dan audit (traceability) — keunggulan dokumentasi array dibanding probe titik tunggal.', 'Interpretasi', 'easy'),
  ('Keselamatan dan praktik baik saat inspeksi ET di lapangan mencakup...',
   '["Mengabaikan kondisi kabel karena tidak mempengaruhi sinyal","Menggunakan radiasi pengion untuk verifikasi","Memastikan grounding/keselamatan listrik instrumen dan menjaga integritas kabel/probe agar pembacaan valid","Menonaktifkan kalibrasi untuk menghemat waktu"]', 2,
   'Meski ET tidak memakai radiasi pengion, praktik keselamatan listrik (grounding, kondisi kabel/konektor) penting. Kabel/probe rusak juga merusak kalibrasi dan menimbulkan indikasi palsu, sehingga harus dijaga integritasnya.', 'Keselamatan', 'easy')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 11 AND ls."orderIndex" = 1 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- ET-L2 Module 1 (1 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (4, 'quiz', 'Mini-quiz — ET-L2 scope', '{"description":"5 soal scope dan technique selection Level II.","questionCount":5,"passingScore":75}', 600, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 1
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- ET-L2 Module 1 mini-quiz (5 questions, step 4)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'ET-L2' AND m."orderIndex" = 1 AND ls."orderIndex" = 4 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'ET', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Berdasarkan SNT-TC-1A / ASNT CP-105, apa perbedaan otoritas inti antara NDT Level I dan Level II pada Eddy Current Testing (ET)?',
   '["Level I dapat menulis prosedur dan menetapkan acceptance criteria, sedangkan Level II hanya menjalankan setup yang sudah ada","Level I melakukan kalibrasi dan akuisisi sesuai instruksi tertulis, sedangkan Level II menyiapkan/kalibrasi peralatan, menafsir & mengevaluasi hasil terhadap code/spec, dan melakukan sign-off","Level I dan Level II memiliki otoritas yang identik; perbedaannya hanya lama pengalaman kerja","Level II hanya berwenang melatih Level I dan tidak boleh menyentuh peralatan inspeksi"]', 1,
   'Per SNT-TC-1A/CP-105, Level I melakukan kalibrasi spesifik dan akuisisi data mengikuti instruksi/prosedur tertulis serta mencatat hasil. Level II menyiapkan dan mengkalibrasi peralatan, menafsir dan mengevaluasi hasil terhadap code/standard/spesifikasi, dan bertanggung jawab atas sign-off. Acceptance criteria pada dasarnya bersumber dari code/owner, dan penyusunan prosedur teknik adalah ranah Level II — bukan Level I.', 'Scope & Otoritas', 'easy'),
  ('Manakah yang merupakan tambahan tanggung jawab khas Level II ET (di atas Level I) menurut ruang lingkup ASNT?',
   '["Hanya membersihkan permukaan dan memasang probe sesuai checklist","Mencatat pembacaan instrumen tanpa interpretasi apa pun","Memilih teknik & frekuensi, melakukan kalibrasi kompleks (mis. setup multi-frequency mix), menafsir indikasi, mengembangkan/menyusun prosedur, dan sign-off hasil","Menentukan kebijakan kualifikasi tingkat perusahaan dan menerbitkan written practice"]', 2,
   'Tanggung jawab tambahan Level II mencakup pemilihan teknik & parameter (frekuensi, mode probe), kalibrasi kompleks seperti tuning multi-frequency mix, interpretasi/evaluasi indikasi, pengembangan & penyusunan prosedur tertulis, dan sign-off. Membersihkan permukaan/mencatat pembacaan adalah ranah Level I. Menerbitkan written practice dan menetapkan kebijakan kualifikasi perusahaan adalah ranah Level III, bukan Level II.', 'Tanggung Jawab Level II', 'medium'),
  ('Sebuah heat exchanger berisi tube carbon steel (ferromagnetik). Level II diminta memilih teknik ET yang tepat untuk mendeteksi wall loss menyeluruh. Pilihan paling sesuai adalah:',
   '["RFT (Remote Field Testing) — through-transmission, fase = kedalaman, sensitivitas OD/ID setara, mampu menjangkau ~full wall pada tube ferromagnetik","Bobbin konvensional absolute tanpa saturasi magnetik, karena paling cepat","Surface/pencil probe frekuensi tinggi yang di-scan secara raster di dalam tube","Array probe frekuensi tinggi karena memberi C-scan resolusi tinggi"]', 0,
   'Pada tube ferromagnetik, permeabilitas tinggi membuat skin depth eddy current sangat kecil sehingga bobbin konvensional tidak menembus dinding (kecuali dengan magnetic saturation, dan tetap terbatas). RFT bekerja melalui through-transmission medan jauh dengan fase berbanding kedalaman, sensitivitas OD/ID setara, dan mampu mengevaluasi ~full wall pada tube ferromagnetik. Pencil/array frekuensi tinggi justru memperkecil skin depth dan tidak cocok untuk wall loss menyeluruh di material ferromagnetik.', 'Pemilihan Teknik', 'medium'),
  ('Untuk mengukur ketebalan dinding tube secara akurat dan kuantitatif (bukan sekadar fase=kedalaman), terutama saat verifikasi pit dalam, metode yang paling tepat dan keterbatasannya adalah:',
   '["MFL — paling akurat untuk wall thickness absolut dan paling lambat","Bobbin differential — memberi nilai wall thickness absolut dengan akuisisi sangat cepat","IRIS — berbasis ultrasonik sehingga memberi pengukuran wall thickness yang akurat, namun relatif lambat","Array eddy current — memberi pengukuran wall thickness absolut paling akurat melalui C-scan"]', 2,
   'IRIS (Internal Rotary Inspection System) berbasis ultrasonik, bukan eddy current, sehingga memberi pengukuran ketebalan dinding yang akurat dan kuantitatif — sangat berguna untuk konfirmasi/sizing pit dalam — namun relatif lambat. MFL justru cepat (untuk deteksi, bukan sizing presisi) pada material ferromagnetik. Bobbin differential peka crack/perubahan mendadak tetapi tidak memberi wall thickness absolut. Array ET tidak memberi pengukuran ketebalan absolut seakurat ultrasonik IRIS.', 'Pemilihan Teknik', 'hard'),
  ('Menurut SNT-TC-1A, dokumen apa yang menetapkan persyaratan rinci kualifikasi & sertifikasi Level II (jam training, jam pengalaman, dan ujian) di sebuah perusahaan?',
   '["ASME Section V Article 8, karena mengatur teknik ET tube","Prosedur teknik (technique procedure) yang ditulis oleh Level II itu sendiri","ISO 9712 secara otomatis menggantikan seluruh persyaratan SNT-TC-1A","Written Practice milik employer (mengacu SNT-TC-1A/CP-105 sebagai panduan rekomendasi)"]', 3,
   'SNT-TC-1A adalah recommended practice; employer wajib menerbitkan Written Practice yang merinci persyaratan kualifikasi/sertifikasi (jam training, jam pengalaman per level/metode, dan ujian) dengan mengacu pada SNT-TC-1A/CP-105. ASME V Article 8 mengatur teknik pemeriksaan ET, bukan persyaratan personel. ISO 9712 adalah skema sertifikasi central/third-party yang berbeda pendekatannya (tidak otomatis menggantikan written practice employer). Technique procedure mengatur cara inspeksi, bukan kualifikasi personel.', 'Sertifikasi & Kualifikasi', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'ET-L2' AND m."orderIndex" = 1 AND ls."orderIndex" = 4 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;
